# --- Кисти для цветного лога ---
function New-Brush([byte]$r, [byte]$g, [byte]$b) {
    $br = [System.Windows.Media.SolidColorBrush]::new([System.Windows.Media.Color]::FromRgb($r, $g, $b))
    $br.Freeze(); $br
}
$brushInfo = New-Brush 0xD6 0xD6 0xE0
$brushWarn = New-Brush 0xE8 0xC3 0x5A
$brushErr  = New-Brush 0xFF 0x76 0x76
$brushOk   = New-Brush 0x7F 0xD1 0x8A
$brushBar  = New-Brush 0x3A 0x7A 0x58
$brushMap  = @{ INFO = $brushInfo; WARN = $brushWarn; ERROR = $brushErr; OK = $brushOk }

# --- Общие стили кнопок (как у T-REX метронома) ---
