<Window xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation"
        xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml"
        Title="T-REX бэкап файловых баз 1С" Width="720" Height="540" MinWidth="560" MinHeight="420"
        WindowStartupLocation="CenterScreen" Background="#FF1E1E26" FontFamily="Segoe UI">
  <Window.Resources>
__STYLES__
    <Style x:Key="GearBtn" TargetType="Button">
      <Setter Property="Background" Value="Transparent"/>
      <Setter Property="BorderThickness" Value="0"/>
      <Setter Property="FontFamily" Value="Segoe MDL2 Assets"/>
      <Setter Property="FontSize" Value="16"/>
      <Setter Property="Foreground" Value="#FFAFC4E8"/>
      <Setter Property="Padding" Value="8,4"/>
      <Setter Property="Cursor" Value="Hand"/>
      <Setter Property="Template">
        <Setter.Value>
          <ControlTemplate TargetType="Button">
            <Border Background="{TemplateBinding Background}" CornerRadius="6" Padding="{TemplateBinding Padding}">
              <ContentPresenter HorizontalAlignment="Center" VerticalAlignment="Center"/>
            </Border>
            <ControlTemplate.Triggers>
              <Trigger Property="IsMouseOver" Value="True">
                <Setter Property="Background" Value="#FF2E2E40"/>
              </Trigger>
              <Trigger Property="IsEnabled" Value="False">
                <Setter Property="Opacity" Value="0.35"/>
              </Trigger>
            </ControlTemplate.Triggers>
          </ControlTemplate>
        </Setter.Value>
      </Setter>
    </Style>
  </Window.Resources>
  <Grid Margin="14">
    <Grid.RowDefinitions>
      <RowDefinition Height="Auto"/>
      <RowDefinition Height="Auto"/>
      <RowDefinition Height="Auto"/>
      <RowDefinition Height="*"/>
      <RowDefinition Height="Auto"/>
      <RowDefinition Height="Auto"/>
    </Grid.RowDefinitions>

    <!-- шапка -->
    <DockPanel Grid.Row="0" Margin="0,0,0,10">
      <Button x:Name="BtnSettings" DockPanel.Dock="Right" Style="{StaticResource GearBtn}"
              Content="&#xE713;" ToolTip="Настройки (config.json)"/>
      <StackPanel Orientation="Horizontal">
        <TextBlock x:Name="HeaderText" Text="T-REX бэкап файловых баз 1С" FontSize="16" FontWeight="Bold" Foreground="#FF7FB4FF" VerticalAlignment="Center"/>
        <TextBlock x:Name="SubHeaderText" Text="v1.0" FontSize="10" Foreground="#FF70708C" VerticalAlignment="Center" Margin="4,4,0,0"/>
      </StackPanel>
    </DockPanel>

    <!-- текущий этап -->
    <TextBlock x:Name="PhaseText" Grid.Row="1" Text="Готов к запуску" FontSize="12"
               Foreground="#FFD6D6E0" Margin="0,0,0,4" TextTrimming="CharacterEllipsis"/>

    <!-- общий прогресс -->
    <ProgressBar x:Name="Progress" Grid.Row="2" Height="8" Minimum="0" Maximum="1" Value="0"
                 Background="#FF2A2A38" Foreground="#FF3A7A58" BorderThickness="0" Margin="0,0,0,8"/>

    <!-- лог -->
    <Border Grid.Row="3" Background="#FF14141C" BorderBrush="#FF33334A" BorderThickness="1" CornerRadius="8" Padding="6">
      <RichTextBox x:Name="LogBox" Background="Transparent" Foreground="#FFD6D6E0"
