    <!-- счётчики + путь конфига -->
    <DockPanel Grid.Row="4" Margin="0,8,0,0">
      <TextBlock x:Name="CountersText" DockPanel.Dock="Left" Text="Успешно: 0   Ошибки: 0"
                 FontSize="12" Foreground="#FFD6D6E0"/>
      <TextBlock x:Name="ConfigText" Text="" FontSize="11" Foreground="#FF70708C"
                 HorizontalAlignment="Right" TextTrimming="CharacterEllipsis" Margin="12,0,0,0"/>
