# имя/версия в заголовке и шапке окна — из единой точки ($AppName/$AppVersion)
$win.Title = $AppTitle
$win.FindName('HeaderText').Text = $AppName
$win.FindName('SubHeaderText').Text = "v$AppVersion · GUI для backup-1c.ps1"

# иконка приложения (T-REX с чемоданом), запасной вариант — общая T-REX из корня утилит
foreach ($ico in @(
    (Join-Path $appDir 'T-REX-backup.ico'),
    (Join-Path $appDir 'T-REX.ico'),
    (Join-Path (Split-Path -Parent $appDir) 'T-REX.ico')
)) {
    if (Test-Path -LiteralPath $ico) {
        try { $win.Icon = [System.Windows.Media.Imaging.BitmapFrame]::Create([Uri]$ico) } catch { }
        break
    }
}

$ConfigText.Text = "Конфиг: $ConfigPath"

# --- Вывод строки в цветной лог главного окна ---
function Add-UiLog {
    param([string]$Line, [string]$Level = 'INFO')
    $range = New-Object System.Windows.Documents.TextRange($LogBox.Document.ContentEnd, $LogBox.Document.ContentEnd)
    $range.Text = $Line + [Environment]::NewLine
    if ($brushMap.ContainsKey($Level)) {
        $range.ApplyPropertyValue([System.Windows.Documents.TextElement]::ForegroundProperty, $brushMap[$Level])
    }
    $LogBox.ScrollToEnd()
}
function Add-UiMsg {
    param([string]$Text, [string]$Level = 'INFO')
    Add-UiLog ('{0:yyyy-MM-dd HH:mm:ss} [{1}] {2}' -f (Get-Date), $Level, $Text) $Level
}

# --- ntfy: push-уведомления об итоге бэкапа ------------------------------------------
# Используются окном настроек (кнопка «Тест») и режимом -TestNotify.
# Копии этих функций живут ВНУТРИ $script:backupWorker: фоновый runspace воркера
# функций главной сессии не видит (тот же паттерн, что у Write-Log воркера).
function Get-NtfyPlainPassword {
    # DPAPI-расшифровка пароля (ConvertFrom-SecureString без ключа = CurrentUser):
    # расшифровывается только под тем же пользователем на той же машине
    param([string]$PasswordEnc)
    if ([string]::IsNullOrWhiteSpace($PasswordEnc)) { return $null }
    try {
        $sec = ConvertTo-SecureString $PasswordEnc
        $bstr = [Runtime.InteropServices.Marshal]::SecureStringToBSTR($sec)
        try   { return [Runtime.InteropServices.Marshal]::PtrToStringBSTR($bstr) }
        finally { [Runtime.InteropServices.Marshal]::ZeroFreeBSTR($bstr) }
    }
    catch { return $null }
}
function Send-NtfyPush {
    # Два способа отправки ntfy (Mode):
    #   json  — JSON-API: POST на корень сервера, все параметры в JSON-теле
    #           (\uXXXX-экранирование кириллицы; заголовки X-Title/X-Tags не используются
    #           именно из-за кириллицы: HTTP-заголовки не бывают не-ASCII, 5.1 искажает);
    #   topic — POST прямо на /<топик>: тело = текст сообщения (кириллица безопасна,
    #           кодировка проверена живьём на 5.1 и pwsh), параметры — заголовками
    #           X-Priority/X-Tags (ASCII). Заголовок сообщения уходит первой строкой тела.
    param([string]$Url, [string]$Topic, [string]$User, [string]$Password,
          [string]$Title, [string]$Message,
          [ValidateSet('min','low','default','high','max')] [string]$Priority = 'default',
          [string[]]$Tags = @(), [int]$TimeoutSec = 15,
          [ValidateSet('json','topic')] [string]$Mode = 'json')
    $headers = @{}
    if ($User) {
        $auth = [Convert]::ToBase64String([Text.Encoding]::ASCII.GetBytes("${User}:${Password}"))
        $headers['Authorization'] = "Basic $auth"
    }
    [System.Net.ServicePointManager]::Expect100Continue = $false
    if ($Mode -eq 'topic') {
        # алиасы min/default/high ВАЛИДНЫ именно в заголовке X-Priority (в JSON нужно число)
        $headers['X-Priority'] = $Priority
        if ($Tags.Count -gt 0) { $headers['X-Tags'] = ($Tags -join ',') }
        $body = if ($Title) { "$Title`n$Message" } else { $Message }
        Invoke-RestMethod -Uri ($Url.TrimEnd('/') + '/' + $Topic) -Method Post -Headers $headers `
            -ContentType 'text/plain; charset=utf-8' -Body $body -TimeoutSec $TimeoutSec | Out-Null
        return
    }
    # JSON-API ntfy ждёт priority ЧИСЛОМ (1..5); строковые алиасы min/default/high валидны
    # только для заголовка X-Priority — строка в JSON даёт 400 «invalid request»
    $prMap = @{ min = 1; low = 2; default = 3; high = 4; max = 5 }
    $payload = @{ topic = $Topic; message = $Message; title = $Title; priority = $prMap[$Priority] }
    if ($Tags.Count -gt 0) { $payload['tags'] = @($Tags) }
    $json = $payload | ConvertTo-Json -Compress
    # Две ловушки Invoke-RestMethod (из-за них ntfy отвечал 400 «topic name is not allowed»):
    # 1) byte[]-тело при application/json уходит обрезком (уходило «123» вместо JSON) —
    #    слать ASCII-строкой, кириллицу экранируя в \uXXXX (валидный JSON, ntfy декодирует);
    # 2) .NET шлёт «Expect: 100-continue», на котором запрос умирает за docker-прокси ntfy — выключить.
    $jsonAscii = [Regex]::Replace($json, '[^\x20-\x7E]', { param($m) '\u{0:x4}' -f [int][char]$m.Value })
    Invoke-RestMethod -Uri ($Url.TrimEnd('/') + '/') -Method Post -Headers $headers `
        -ContentType 'application/json' -Body $jsonAscii -TimeoutSec $TimeoutSec | Out-Null
}
function Get-NtfyWatchState {
    # Состояние «периода наблюдения» ntfy — сколько дней от первого прогона слать итоги
    # (приёмка после установки утилиты в организацию). WatchDays: 0/отсутствие = бессрочно
    # (обратная совместимость со старыми конфигами). Дата — локальная, формат yyyy-MM-dd,
    # парсится ParseExact+InvariantCulture (культура машины не должна влиять).
    # Возвращает hashtable: Mode = always|activate|active|final|done,
    #   WatchDays (int), ActiveUntil ([datetime]$null), DaysLeft (int; 0 = сегодня последний).
    param($Ntfy)
    $res = @{ Mode = 'always'; WatchDays = 0; ActiveUntil = $null; DaysLeft = 0 }
    if (-not $Ntfy) { return $res }
    $wdRaw = "$($Ntfy.WatchDays)".Trim()
    if ($wdRaw -match '^\d+$') { $res.WatchDays = [int]$wdRaw }
    if ($res.WatchDays -le 0) { return $res }
    $until = $null
    $auRaw = "$($Ntfy.ActiveUntil)".Trim()
    if ($auRaw -match '^\d{4}-\d{2}-\d{2}$') {
        try { $until = [datetime]::ParseExact($auRaw, 'yyyy-MM-dd', [Globalization.CultureInfo]::InvariantCulture) }
        catch { $until = $null }
    }
    if (-not $until) { $res.Mode = 'activate'; return $res }   # срок ещё не стартовал
    $res.ActiveUntil = $until.Date
    $res.DaysLeft = [int]($until.Date - (Get-Date).Date).TotalDays
    if ($res.DaysLeft -ge 0) { $res.Mode = 'active' }
    elseif ($Ntfy.FinalNoticeSent -eq $true) { $res.Mode = 'done' }
    else { $res.Mode = 'final' }
    return $res
}
function Get-NtfyWatchStatusText {
    # Строка статуса периода наблюдения для окна настроек (по СОХРАНЁННОМУ конфигу)
    param($Ntfy)
    $st = Get-NtfyWatchState $Ntfy
    switch ($st.Mode) {
        'always'   { return 'уведомления без ограничения срока' }
        'activate' { return "срок начнётся с первого прогона ($($st.WatchDays) дн.)" }
        'active'   {
            if ($st.DaysLeft -le 0) { return 'сегодня последний день наблюдения' }
            elseif ($st.DaysLeft -eq 1) { return ('до {0:dd.MM.yyyy} — завтра последний день' -f $st.ActiveUntil) }
            else { return ('до {0:dd.MM.yyyy} (осталось {1} дн.)' -f $st.ActiveUntil, $st.DaysLeft) }
        }
        'final'    { return ('истёк {0:dd.MM.yyyy} — после следующего прогона итоги отключатся (можно продлить)' -f $st.ActiveUntil) }
        'done'     { return ('завершён {0:dd.MM.yyyy} — итоги не отправляются (можно продлить)' -f $st.ActiveUntil) }
    }
    return ''
}
$script:backupWorker = {
    param($sync)

    $config      = $sync.Config
    $destination = [Environment]::ExpandEnvironmentVariables([string]$config.Destination)
    $logQueue    = $sync.LogQueue

    $ok = 0; $failed = 0; $completed = $false; $aborted = $false; $fatalReason = ''
    $runRows = New-Object System.Collections.ArrayList   # построчный итог: Name/Status(ok|error)/Detail(архив или причина)
    $logPath = Join-Path $destination ('backup_{0:yyyy-MM-dd_HH-mm-ss}.log' -f (Get-Date))
    $sync.LogPath = $logPath

    function Write-Log {
        param([string]$Message, [ValidateSet('INFO','WARN','ERROR','OK')] [string]$Level = 'INFO')
        $line = '{0:yyyy-MM-dd HH:mm:ss} [{1}] {2}' -f (Get-Date), $Level, $Message
        [void]$logQueue.Add(@{ Line = $line; Level = $Level })
        try { Add-Content -LiteralPath $logPath -Value $line -Encoding UTF8 } catch { }
    }

    # SQLite-лог (опционально, как в консольном скрипте)
    $dbConn = $null; $runId = $null
    function Invoke-Db {
        param([string]$Sql, [hashtable]$Params = @{})
        if (-not $dbConn) { return $null }
        $cmd = $dbConn.CreateCommand()
        try {
            $cmd.CommandText = $Sql
            foreach ($k in $Params.Keys) { [void]$cmd.Parameters.AddWithValue("@$k", $Params[$k]) }
            return $cmd.ExecuteScalar()
        }
        finally { $cmd.Dispose() }
    }
    function ConvertFrom-GzipB64 {
        param([string]$B64Text)
        $bytes = [Convert]::FromBase64String(($B64Text -replace '\s', ''))
        $inMs = [IO.MemoryStream]::new($bytes)
        $gz = [IO.Compression.GZipStream]::new($inMs, [IO.Compression.CompressionMode]::Decompress)
        $out = [IO.MemoryStream]::new()
        $gz.CopyTo($out)
        $gz.Dispose()
        $out.ToArray()
    }
    function Find-SqliteDll {
        param([string]$AppDir, $Embedded)
        # 1) встроенный драйвер (gzip+base64 в теле скрипта): распаковка в %LOCALAPPDATA%;
        #    сборка выбирается по редакции PowerShell (exe от ps2exe работает под 5.1)
        if ($Embedded -and [Environment]::Is64BitProcess) {
            $pair = $null; $subDir = ''
            if ($PSVersionTable.PSEdition -eq 'Core') {
                if ($Embedded.ManagedCore) { $pair = @{ Managed = $Embedded.ManagedCore; Interop = $Embedded.InteropCore }; $subDir = 'sqlite-x64-netcore' }
            }
            elseif ($Embedded.ManagedFx) {
                $pair = @{ Managed = $Embedded.ManagedFx; Interop = $Embedded.InteropFx }; $subDir = 'sqlite-x64-netfx'
            }
            if ($pair) {
                try {
                    $libDir = Join-Path ([Environment]::GetFolderPath('LocalApplicationData')) "T-REX-Backup1C\$subDir"
                    New-Item -ItemType Directory -Path $libDir -Force | Out-Null
                    $managed = Join-Path $libDir 'System.Data.SQLite.dll'
                    $interop = Join-Path $libDir 'SQLite.Interop.dll'
                    foreach ($f in @(@{ File = $managed; Blob = $pair.Managed }, @{ File = $interop; Blob = $pair.Interop })) {
                        $bytes = ConvertFrom-GzipB64 $f.Blob
                        $fresh = if (Test-Path -LiteralPath $f.File) { (Get-Item -LiteralPath $f.File).Length -eq $bytes.Length } else { $false }
                        if (-not $fresh) { [IO.File]::WriteAllBytes($f.File, $bytes) }
                    }
                    Add-Type -Path $managed -ErrorAction Stop
                    if ('System.Data.SQLite.SQLiteConnection' -as [type]) { return 'embedded' }
                }
                catch {
                    Write-Log "SQLite: не удалось загрузить встроенный драйвер ($($_.Exception.Message)) - пробую запасные варианты." WARN
                }
            }
        }
        # 2) dll рядом со скриптом (как в консольном backup-1c.ps1)
        foreach ($p in @(
            (Join-Path $AppDir 'System.Data.SQLite.dll'),
            (Join-Path $AppDir 'lib\System.Data.SQLite.dll')
        )) {
            if (Test-Path -LiteralPath $p) { return $p }
        }
        # 3) модуль PSSQLite
        try {
            Import-Module PSSQLite -ErrorAction Stop
            if ('System.Data.SQLite.SQLiteConnection' -as [type]) { return 'module' }
        } catch { }
        return $null
    }
    function Get-BaseId {
        param([string]$Name, [string]$Path)
        if (-not $dbConn) { return $null }
        [void](Invoke-Db 'INSERT OR IGNORE INTO bases (name, path) VALUES (@n, @p);' @{ n = $Name; p = $Path })
        [void](Invoke-Db 'UPDATE bases SET path = @p, is_active = 1 WHERE name = @n;' @{ n = $Name; p = $Path })
        return Invoke-Db 'SELECT id FROM bases WHERE name = @n;' @{ n = $Name }
    }
    # Копии top-level функций ntfy: runspace воркера функций сессии не видит
    function Get-NtfyPlainPassword {
        param([string]$PasswordEnc)
        if ([string]::IsNullOrWhiteSpace($PasswordEnc)) { return $null }
        try {
            $sec = ConvertTo-SecureString $PasswordEnc
            $bstr = [Runtime.InteropServices.Marshal]::SecureStringToBSTR($sec)
            try   { return [Runtime.InteropServices.Marshal]::PtrToStringBSTR($bstr) }
            finally { [Runtime.InteropServices.Marshal]::ZeroFreeBSTR($bstr) }
        }
        catch { return $null }
    }
    function Send-NtfyPush {
        # Копия top-level Send-NtfyPush (с Mode json|topic) — см. комментарии там.
        param([string]$Url, [string]$Topic, [string]$User, [string]$Password,
              [string]$Title, [string]$Message,
              [ValidateSet('min','low','default','high','max')] [string]$Priority = 'default',
              [string[]]$Tags = @(), [int]$TimeoutSec = 15,
              [ValidateSet('json','topic')] [string]$Mode = 'json')
        $headers = @{}
        if ($User) {
            $auth = [Convert]::ToBase64String([Text.Encoding]::ASCII.GetBytes("${User}:${Password}"))
            $headers['Authorization'] = "Basic $auth"
        }
        [System.Net.ServicePointManager]::Expect100Continue = $false
        if ($Mode -eq 'topic') {
            $headers['X-Priority'] = $Priority
            if ($Tags.Count -gt 0) { $headers['X-Tags'] = ($Tags -join ',') }
            $body = if ($Title) { "$Title`n$Message" } else { $Message }
            Invoke-RestMethod -Uri ($Url.TrimEnd('/') + '/' + $Topic) -Method Post -Headers $headers `
                -ContentType 'text/plain; charset=utf-8' -Body $body -TimeoutSec $TimeoutSec | Out-Null
            return
        }
        # JSON-API ntfy ждёт priority ЧИСЛОМ (1..5); строковые алиасы min/default/high валидны
        # только для заголовка X-Priority — строка в JSON даёт 400 «invalid request»
        $prMap = @{ min = 1; low = 2; default = 3; high = 4; max = 5 }
        $payload = @{ topic = $Topic; message = $Message; title = $Title; priority = $prMap[$Priority] }
        if ($Tags.Count -gt 0) { $payload['tags'] = @($Tags) }
        $json = $payload | ConvertTo-Json -Compress
        # Две ловушки Invoke-RestMethod (из-за них ntfy отвечал 400 «topic name is not allowed»):
        # 1) byte[]-тело при application/json уходит обрезком (уходило «123» вместо JSON) —
        #    слать ASCII-строкой, кириллицу экранируя в \uXXXX (валидный JSON, ntfy декодирует);
        # 2) .NET шлёт «Expect: 100-continue», на котором запрос умирает за docker-прокси ntfy — выключить.
        $jsonAscii = [Regex]::Replace($json, '[^\x20-\x7E]', { param($m) '\u{0:x4}' -f [int][char]$m.Value })
        Invoke-RestMethod -Uri ($Url.TrimEnd('/') + '/') -Method Post -Headers $headers `
            -ContentType 'application/json' -Body $jsonAscii -TimeoutSec $TimeoutSec | Out-Null
    }
    function Get-NtfyWatchState {
        # Копия top-level Get-NtfyWatchState — см. комментарии там.
        param($Ntfy)
        $res = @{ Mode = 'always'; WatchDays = 0; ActiveUntil = $null; DaysLeft = 0 }
        if (-not $Ntfy) { return $res }
        $wdRaw = "$($Ntfy.WatchDays)".Trim()
        if ($wdRaw -match '^\d+$') { $res.WatchDays = [int]$wdRaw }
        if ($res.WatchDays -le 0) { return $res }
        $until = $null
        $auRaw = "$($Ntfy.ActiveUntil)".Trim()
        if ($auRaw -match '^\d{4}-\d{2}-\d{2}$') {
            try { $until = [datetime]::ParseExact($auRaw, 'yyyy-MM-dd', [Globalization.CultureInfo]::InvariantCulture) }
            catch { $until = $null }
        }
        if (-not $until) { $res.Mode = 'activate'; return $res }
        $res.ActiveUntil = $until.Date
        $res.DaysLeft = [int]($until.Date - (Get-Date).Date).TotalDays
        if ($res.DaysLeft -ge 0) { $res.Mode = 'active' }
        elseif ($Ntfy.FinalNoticeSent -eq $true) { $res.Mode = 'done' }
        else { $res.Mode = 'final' }
        return $res
    }
    function Set-NtfyWatchConfig {
        # Точечная запись полей периода наблюдения в config.json ИЗ ВОРКЕРА: файл
        # читается с диска заново, меняются ТОЛЬКО ActiveUntil/FinalNoticeSent в секции
        # Ntfy (остальные поля и чужие правки не затираются). Возвращает $true при успехе.
        param([string]$ConfigFile, [string]$ActiveUntil, [bool]$FinalSent)
        try {
            $cfgW = [IO.File]::ReadAllText($ConfigFile) | ConvertFrom-Json
            if (-not $cfgW.Ntfy) {
                $cfgW | Add-Member -MemberType NoteProperty -Name 'Ntfy' -Value ([pscustomobject]@{}) -Force
            }
            $cfgW.Ntfy | Add-Member -MemberType NoteProperty -Name 'ActiveUntil' -Value $ActiveUntil -Force
            $cfgW.Ntfy | Add-Member -MemberType NoteProperty -Name 'FinalNoticeSent' -Value $FinalSent -Force
            $jsonW = ConvertTo-Json $cfgW -Depth 6
            [IO.File]::WriteAllText($ConfigFile, $jsonW, [Text.UTF8Encoding]::new($false))
            return $true
        }
        catch { return $false }
    }
    function Send-NtfyRunSummary {
        # Итоговый push по результатам прогона. Вызывается в finally воркера —
        # единственная точка, покрывающая все исходы (включая ранние фатальные
        # return: они тоже проходят через внешний finally). Сбой отправки бэкап не роняет.
        # Тело сообщения построчное: «<база из конфига> — OK (<имя архива>)» /
        # «<база> — Ошибка (<причина>)», в конце итог и дата. В заголовке — имя
        # компьютера ([ИМЯ-ПК] …): у установок в разные организации так видно, чей итог.
        # Период наблюдения: WatchDays > 0 ограничивает, сколько дней от первого
        # прогона слать итоги; дата окончания пишется в конфиг при активации,
        # по истечении — один финальный пуш и тишина (детали — Get-NtfyWatchState).
        param($Config, [string]$ConfigPath, [int]$OkCnt, [int]$FailedCnt, [bool]$Aborted, [bool]$Fatal,
              [string]$FatalText, $RunRows)
        $ntfy = $Config.Ntfy
        if (-not ($ntfy -and $ntfy.Enabled -and $ntfy.Url -and $ntfy.Topic)) { return }
        $pass = Get-NtfyPlainPassword ([string]$ntfy.PasswordEnc)
        if (-not $pass) { Write-Log 'ntfy: пароль не задан/не расшифровывается — уведомление пропущено.' WARN; return }
        $cmp = $env:COMPUTERNAME
        $stampTxt = '{0:dd.MM.yyyy HH:mm}' -f (Get-Date)
        $mode = [string]$ntfy.Mode
        if ($mode -ne 'topic') { $mode = 'json' }   # отсутствие/мусор в конфиге = прежнее поведение
        $watch = Get-NtfyWatchState $ntfy
        if ($watch.Mode -eq 'done') {
            Write-Log ('ntfy: период наблюдения завершён {0:dd.MM.yyyy} — итоговое уведомление не отправляется.' -f $watch.ActiveUntil)
            return
        }
        if ($watch.Mode -eq 'final') {
            # финальный пуш об окончании наблюдения — ОДИН раз: сначала фиксируем флаг
            # в конфиге (не записался — не шлём, иначе каждый прогон слал бы финал заново)
            if (-not (Set-NtfyWatchConfig -ConfigFile $ConfigPath -ActiveUntil ($watch.ActiveUntil.ToString('yyyy-MM-dd')) -FinalSent $true)) {
                Write-Log 'ntfy: не удалось записать флаг окончания наблюдения в конфиг — финальное уведомление не отправляется.' WARN
                return
            }
            try {
                Send-NtfyPush -Url ([string]$ntfy.Url) -Topic ([string]$ntfy.Topic) `
                    -User ([string]$ntfy.User) -Password $pass `
                    -Title "[$cmp] Наблюдение завершено" `
                    -Message ("Период наблюдения бэкапа (до {0:dd.MM.yyyy}) истёк — автоматические итоги с компьютера $cmp больше не отправляются.`nИтог последнего прогона: OK — $OkCnt, ошибок — $FailedCnt. $stampTxt" -f $watch.ActiveUntil) `
                    -Priority 'default' -Tags @('stopwatch') -Mode $mode
                Write-Log 'ntfy: отправлено финальное уведомление — автоматические итоги отключены.'
            }
            catch { Write-Log "ntfy: финальное уведомление не отправлено: $($_.Exception.Message)" WARN }
            return
        }
        $watchNote = ''
        if ($watch.Mode -eq 'activate') {
            # первый прогон со сроком: фиксируем дату окончания (сегодня + WatchDays-1,
            # т.е. WatchDays календарных дней с итогами включительно) и пересчитываем
            $untilStr = (Get-Date).Date.AddDays($watch.WatchDays - 1).ToString('yyyy-MM-dd')
            if (Set-NtfyWatchConfig -ConfigFile $ConfigPath -ActiveUntil $untilStr -FinalSent $false) {
                Write-Log "ntfy: период наблюдения активирован — итоги отправляются до $untilStr."
                $ntfy | Add-Member -MemberType NoteProperty -Name 'ActiveUntil' -Value $untilStr -Force
                $ntfy | Add-Member -MemberType NoteProperty -Name 'FinalNoticeSent' -Value $false -Force
                $watch = Get-NtfyWatchState $ntfy
            }
            else {
                # конфиг не записался (нет прав?): шлём итог без активации срока,
                # при следующем прогоне попытка повторится
                Write-Log 'ntfy: не удалось записать дату начала периода наблюдения в конфиг — срок не активирован.' WARN
                $watch = @{ Mode = 'always'; WatchDays = $watch.WatchDays; ActiveUntil = $null; DaysLeft = 0 }
            }
        }
        if ($watch.Mode -eq 'active') {
            if ($watch.DaysLeft -le 0) { $watchNote = 'Наблюдение: сегодня последний день.' }
            elseif ($watch.DaysLeft -eq 1) { $watchNote = ('Наблюдение: до {0:dd.MM} — завтра последний день.' -f $watch.ActiveUntil) }
            else { $watchNote = ('Наблюдение: до {0:dd.MM} (осталось {1} дн.).' -f $watch.ActiveUntil, $watch.DaysLeft) }
        }
        $lines = @()
        foreach ($r in @($RunRows)) {
            if ($r.Status -eq 'ok') { $lines += ('{0} — OK ({1})' -f $r.Name, $r.Detail) }
            else { $lines += ('{0} — Ошибка ({1})' -f $r.Name, $r.Detail) }
        }
        if ($Fatal) {
            $t = "[$cmp] Бэкап 1С: СРЫВ"
            $m = if ($FatalText) { "Прогон не выполнен: $FatalText. $stampTxt" } else { "Прогон не выполнен (внутренняя ошибка). $stampTxt" }
            if ($watchNote) { $m = "$m`n$watchNote" }
            $pr = 'high'; $tags = @('rotating_light')
        }
        elseif ($Aborted) {
            $t = "[$cmp] Бэкап 1С: прерван"
            $m = ((@("Остановлено пользователем. Успешно: $OkCnt, ошибок: $FailedCnt.") + $lines + @($stampTxt)) -join "`n")
            if ($watchNote) { $m = "$m`n$watchNote" }
            $pr = 'default'; $tags = @('pause_button')
        }
        elseif ($FailedCnt -gt 0) {
            $t = "[$cmp] Бэкап 1С: ошибки ($FailedCnt)"
            $m = (($lines + @("Итог: OK — $OkCnt, ошибки — $FailedCnt.") + @($stampTxt)) -join "`n")
            if ($watchNote) { $m = "$m`n$watchNote" }
            $pr = 'high'; $tags = @('warning')
        }
        else {
            $t = "[$cmp] Бэкап 1С: ОК"
            $m = (($lines + @("Итог: все базы OK ($OkCnt).") + @($stampTxt)) -join "`n")
            if ($watchNote) { $m = "$m`n$watchNote" }
            $pr = 'min'; $tags = @('white_check_mark')
        }
        try {
            Send-NtfyPush -Url ([string]$ntfy.Url) -Topic ([string]$ntfy.Topic) `
                -User ([string]$ntfy.User) -Password $pass -Title $t -Message $m -Priority $pr -Tags $tags `
                -Mode $mode
            Write-Log "ntfy: итоговое уведомление отправлено (топик $($ntfy.Topic), приоритет $pr, способ $mode)."
        }
        catch { Write-Log "ntfy: не удалось отправить уведомление: $($_.Exception.Message)" WARN }
    }

    $tempRoot = $null
    try {
        $sync.Phase = 'Подготовка'
        $sync.Total = @($config.Bases).Count

        # --- Каталог назначения ---
        if (-not (Test-Path -LiteralPath $destination -PathType Container)) {
            Write-Log "Каталог назначения недоступен или не существует: $destination" ERROR
            $sync.FatalError = $true; $sync.ExitCode = 1; $fatalReason = "каталог назначения не существует: $destination"; return
        }
        $probe = Join-Path $destination ("~write-probe-" + [Guid]::NewGuid().ToString('N'))
        try {
            [IO.File]::WriteAllText($probe, '')
            Remove-Item -LiteralPath $probe -Force
        }
        catch {
            Write-Log "Каталог назначения недоступен для записи: $destination ($($_.Exception.Message))" ERROR
            $sync.FatalError = $true; $sync.ExitCode = 1; $fatalReason = 'каталог назначения не доступен для записи'; return
        }

        # --- Поиск 7-Zip ---
        $sevenZip = $null
        if ($config.SevenZipPath -and (Test-Path -LiteralPath $config.SevenZipPath)) {
            $sevenZip = $config.SevenZipPath
        }
        else {
            $candidates = @("$env:ProgramFiles\7-Zip\7z.exe", "${env:ProgramFiles(x86)}\7-Zip\7z.exe")
            foreach ($p in $candidates) { if (Test-Path -LiteralPath $p) { $sevenZip = $p; break } }
            if (-not $sevenZip) {
                $fromPath = Get-Command 7z.exe -ErrorAction SilentlyContinue
                if ($fromPath) { $sevenZip = $fromPath.Source }
            }
        }
        if (-not $sevenZip) {
            Write-Log '7-Zip не найден. Укажите путь в настройках ( SevenZipPath ) или установите 7-Zip.' ERROR
            $sync.FatalError = $true; $sync.ExitCode = 1; $fatalReason = '7-Zip не найден'; return
        }

        # --- Каталог временных копий (TempDir в конфиге; пусто/отсутствие = системный %TEMP%) ---
        # Базы копируются сюда перед упаковкой; проверяем как назначение — тихо подменять
        # выбранный пользователем диск системным %TEMP% нельзя (можно незаметно переполнить C:)
        $tempBase = [IO.Path]::GetTempPath()
        if ($config.TempDir) {
            $tempBase = [Environment]::ExpandEnvironmentVariables([string]$config.TempDir)
            if (-not (Test-Path -LiteralPath $tempBase -PathType Container)) {
                Write-Log "Каталог временных копий не существует: $tempBase (поле «Каталог временных копий» в настройках)" ERROR
                $sync.FatalError = $true; $sync.ExitCode = 1; $fatalReason = "каталог временных копий не существует: $tempBase"; return
            }
            $probeT = Join-Path $tempBase ("~write-probe-" + [Guid]::NewGuid().ToString('N'))
            try {
                [IO.File]::WriteAllText($probeT, '')
                Remove-Item -LiteralPath $probeT -Force
            }
            catch {
                Write-Log "Каталог временных копий недоступен для записи: $tempBase ($($_.Exception.Message))" ERROR
                $sync.FatalError = $true; $sync.ExitCode = 1; $fatalReason = 'каталог временных копий не доступен для записи'; return
            }
        }

        Write-Log "Старт бэкапа. Конфиг: $($sync.ConfigPath)"
        Write-Log "Назначение: $destination"
        Write-Log "7-Zip: $sevenZip"
        Write-Log "Временный каталог: $tempBase"

        # --- KeepDays (дни хранения архивов; бывш. КоличествоДнейАктуальности — читается для совместимости) ---
        $keepDays = $null; $cutoffDate = $null
        $keepDaysRaw = $config.KeepDays
        if ($null -eq $keepDaysRaw) { $keepDaysRaw = $config.КоличествоДнейАктуальности }
        if ($null -ne $keepDaysRaw) {
            $rawDays = "$keepDaysRaw".Trim()
            if ($rawDays -match '^\d+$') { $keepDays = [int]$rawDays }
            else { Write-Log "Некорректное значение KeepDays в конфиге: '$rawDays'" WARN }
        }
        if ($null -eq $keepDays) {
            Write-Log 'KeepDays не задан в конфиге - ротация ПРОПУЩЕНА.' WARN
        }
        elseif ($keepDays -eq 0) {
            Write-Log 'Ротация отключена (KeepDays = 0).'
        }
        else {
            $cutoffDate = (Get-Date).Date.AddDays(-$keepDays)
            Write-Log ("Ротация: будут удалены архивы с датой в имени раньше {0:dd.MM.yyyy}." -f $cutoffDate)
        }

        # --- Инициализация SQLite ---
        $dbPath = if ($config.LogDb) { [Environment]::ExpandEnvironmentVariables([string]$config.LogDb) }
                  else { Join-Path $destination 'backup_log.db' }
        $sqliteDll = $null
        if ($config.LogSqliteEnabled -eq $false) {
            # флаг «БД логов (SQLite)» в настройках выключен: прогон без записи в БД
            Write-Log 'SQLite: запись логов отключена в настройках — прогон идёт без БД.'
        }
        elseif (-not ($sqliteDll = Find-SqliteDll $sync.AppDir $sync.EmbeddedSqlite)) {
            Write-Log 'SQLite: драйвер не найден (встроенный блок пуст, dll рядом со скриптом нет, модуль PSSQLite не установлен) - запись в БД отключена.' WARN
        }
        else {
            try {
                if ($sqliteDll -eq 'embedded') {
                    Write-Log "SQLite: используется встроенный драйвер ($([Environment]::GetFolderPath('LocalApplicationData'))\T-REX-Backup1C)."
                }
                elseif ($sqliteDll -ne 'module') { Add-Type -Path $sqliteDll -ErrorAction Stop }
                $dbConn = New-Object System.Data.SQLite.SQLiteConnection("Data Source=`"$dbPath`";Version=3;")
                $dbConn.Open()
                [void](Invoke-Db 'PRAGMA journal_mode=WAL;')
                Invoke-Db 'CREATE TABLE IF NOT EXISTS bases (id INTEGER PRIMARY KEY, name TEXT NOT NULL UNIQUE, path TEXT NOT NULL, is_active INTEGER NOT NULL DEFAULT 1);'
                Invoke-Db 'CREATE TABLE IF NOT EXISTS runs (id INTEGER PRIMARY KEY, started_at TEXT NOT NULL, finished_at TEXT, config_path TEXT, destination TEXT, keep_days INTEGER, status TEXT NOT NULL DEFAULT ''running'', ok_count INTEGER NOT NULL DEFAULT 0, failed_count INTEGER NOT NULL DEFAULT 0, exit_code INTEGER, log_file TEXT);'
                Invoke-Db 'CREATE TABLE IF NOT EXISTS run_results (id INTEGER PRIMARY KEY, run_id INTEGER NOT NULL REFERENCES runs(id) ON DELETE CASCADE, base_id INTEGER REFERENCES bases(id), base_name TEXT NOT NULL, status TEXT NOT NULL, archive_name TEXT, archive_size_mb REAL, duration_sec REAL, error_text TEXT);'
                Invoke-Db 'CREATE TABLE IF NOT EXISTS rotation_events (id INTEGER PRIMARY KEY, run_id INTEGER NOT NULL REFERENCES runs(id) ON DELETE CASCADE, action TEXT NOT NULL, archive_name TEXT, cutoff_date TEXT, detail TEXT);'
                Invoke-Db 'CREATE INDEX IF NOT EXISTS idx_results_run ON run_results(run_id);'
                Invoke-Db 'CREATE INDEX IF NOT EXISTS idx_results_base ON run_results(base_id);'
                Invoke-Db 'CREATE INDEX IF NOT EXISTS idx_rotation_run ON rotation_events(run_id);'
                Invoke-Db 'CREATE INDEX IF NOT EXISTS idx_runs_started ON runs(started_at);'
                $runId = Invoke-Db "INSERT INTO runs (started_at, config_path, destination, keep_days, status, log_file)
                                    VALUES (datetime('now','localtime'), @cfg, @dst, @kd, 'running', @log);
                                    SELECT last_insert_rowid();" @{
                    cfg = $sync.ConfigPath; dst = $destination
                    kd  = $keepDays;       log = $logPath }
                Write-Log "SQLite: лог пишется в $dbPath (run_id=$runId)"
            }
            catch {
                Write-Log "SQLite: не удалось инициализировать БД ($dbPath): $($_.Exception.Message) - запись в БД отключена." WARN
                if ($dbConn) { try { $dbConn.Close() } catch { } }
                $dbConn = $null; $runId = $null
            }
        }

        # --- Бэкап баз ---
        $stamp = Get-Date -Format 'yyyy-MM-dd_HH-mm-ss'
        $tempRoot = Join-Path $tempBase ("1c-backup-" + $stamp)
        New-Item -ItemType Directory -Path $tempRoot -Force | Out-Null

        try {
            $i = 0
            foreach ($base in @($config.Bases)) {
                $i++
                if ($sync.CancelRequested) {
                    $aborted = $true
                    Write-Log 'Остановлено пользователем.' WARN
                    break
                }
                $sync.Phase = "База $i/$($sync.Total): $($base.Name)"
                $sync.Progress = $i

                $name = $base.Name
                $source = [Environment]::ExpandEnvironmentVariables([string]$base.Path)

                # если указан каталог базы - достраиваем имя файла
                if (Test-Path -LiteralPath $source -PathType Container) {
                    $source = Join-Path $source '1Cv8.1CD'
                }
                if ([string]::IsNullOrWhiteSpace($name)) {
                    $name = [IO.Path]::GetFileNameWithoutExtension((Split-Path $source -Parent))
                }

                $sw = [System.Diagnostics.Stopwatch]::StartNew()

                if (-not (Test-Path -LiteralPath $source -PathType Leaf)) {
                    Write-Log "БАЗА НЕ НАЙДЕНА: $name -> $source" ERROR
                    Invoke-Db "INSERT INTO run_results (run_id, base_id, base_name, status, duration_sec, error_text)
                               VALUES (@run, @bid, @name, 'not_found', @dur, @err)" @{
                        run = $runId; bid = (Get-BaseId $name $base.Path)
                        name = $name; dur = [math]::Round($sw.Elapsed.TotalSeconds, 1); err = "не найден: $source" }
                    $failed++; $sync.Failed = $failed
                    [void]$runRows.Add([pscustomobject]@{ Name = $name; Status = 'error'; Detail = 'база не найдена' })
                    continue
                }

                $baseTempDir = Join-Path $tempRoot $name
                $tempCopy = Join-Path $baseTempDir '1Cv8.1CD'
                $archiveName = "{0}_{1}.7z" -f $name, $stamp
                $tempArchive = Join-Path $tempRoot $archiveName
                $finalArchive = Join-Path $destination $archiveName

                try {
                    New-Item -ItemType Directory -Path $baseTempDir -Force | Out-Null
                    $sync.Phase = "База $i/$($sync.Total): $name — копирование"
                    Write-Log "Копирование: $source -> $tempCopy"
                    Copy-Item -LiteralPath $source -Destination $tempCopy -Force

                    $sync.Phase = "База $i/$($sync.Total): $name — архивация"
                    Write-Log "Архивация: $tempArchive"
                    # пакуем из папки базы, чтобы внутри архива файл звался 1Cv8.1CD
                    Push-Location $baseTempDir
                    try {
                        & $sevenZip @('a', '-t7z', '-mx=5', '-y', $tempArchive, '1Cv8.1CD') | Out-Null
                    }
                    finally {
                        Pop-Location
                    }
                    if ($LASTEXITCODE -ne 0) {
                        throw "7-Zip завершился с кодом $LASTEXITCODE"
                    }

                    Write-Log "Перенос архива: $finalArchive"
                    Move-Item -LiteralPath $tempArchive -Destination $finalArchive -Force

                    $sizeMb = [math]::Round((Get-Item -LiteralPath $finalArchive).Length / 1MB, 2)
                    Write-Log "OK: $name ($sizeMb МБ)" OK
                    $ok++; $sync.Ok = $ok
                    [void]$runRows.Add([pscustomobject]@{ Name = $name; Status = 'ok'; Detail = $archiveName })
                    Invoke-Db "INSERT INTO run_results (run_id, base_id, base_name, status, archive_name, archive_size_mb, duration_sec)
                               VALUES (@run, @bid, @name, 'ok', @arch, @sz, @dur)" @{
                        run = $runId; bid = (Get-BaseId $name $base.Path)
                        name = $name; arch = $archiveName; sz = $sizeMb
                        dur = [math]::Round($sw.Elapsed.TotalSeconds, 1) }
                }
                catch {
                    Write-Log "ОШИБКА для '$name': $($_.Exception.Message)" ERROR
                    $failed++; $sync.Failed = $failed
                    $errShort = "$($_.Exception.Message)".Trim()
                    if ($errShort.Length -gt 60) { $errShort = $errShort.Substring(0, 60) + '…' }
                    [void]$runRows.Add([pscustomobject]@{ Name = $name; Status = 'error'; Detail = $errShort })
                    Invoke-Db "INSERT INTO run_results (run_id, base_id, base_name, status, duration_sec, error_text)
                               VALUES (@run, @bid, @name, 'error', @dur, @err)" @{
                        run = $runId; bid = (Get-BaseId $name $base.Path)
                        name = $name; dur = [math]::Round($sw.Elapsed.TotalSeconds, 1)
                        err = $_.Exception.Message }
                    if (Test-Path -LiteralPath $tempArchive) { Remove-Item -LiteralPath $tempArchive -Force -ErrorAction SilentlyContinue }
                    if (Test-Path -LiteralPath $finalArchive) { Remove-Item -LiteralPath $finalArchive -Force -ErrorAction SilentlyContinue }
                }
            }

            if (-not $aborted) {
                # --- Ротация (только при полном успехе и заданном KeepDays) ---

                # базы, которых больше нет в конфиге, помечаем неактивными (историю не трогаем)
                if ($dbConn) {
                    [void](Invoke-Db 'UPDATE bases SET is_active = 0;')
                    foreach ($b in @($config.Bases)) {
                        [void](Invoke-Db 'UPDATE bases SET is_active = 1 WHERE name = @n;' @{ n = $b.Name })
                    }
                }

                if ($null -eq $keepDays -or $keepDays -eq 0) {
                    if ($null -eq $keepDays) {
                        Invoke-Db "INSERT INTO rotation_events (run_id, action, detail)
                                   VALUES (@run, 'skipped', @d)" @{ run = $runId; d = 'KeepDays не задан' }
                    }
                    else {
                        Invoke-Db "INSERT INTO rotation_events (run_id, action, detail)
                                   VALUES (@run, 'disabled', @d)" @{ run = $runId; d = 'KeepDays = 0' }
                    }
                }
                elseif ($failed -gt 0) {
                    Write-Log "Ротация ПРОПУЩЕНА: бэкап завершился с ошибками (успешно: $ok, с ошибками: $failed) - старые архивы оставлены как страховка." WARN
                    Invoke-Db "INSERT INTO rotation_events (run_id, action, detail)
                               VALUES (@run, 'skipped', @d)" @{ run = $runId; d = "бэкап с ошибками (ok=$ok, failed=$failed)" }
                }
                else {
                    $deletedCount = 0
                    # имена файлов вида <Имя>_<штамп>.7z; дата берётся из имени, а не LastWriteTime
                    $allArchives = @(Get-ChildItem -LiteralPath $destination -Filter '*.7z' -File)
                    foreach ($base in @($config.Bases)) {
                        $pattern = '^' + [regex]::Escape($base.Name) + '_(\d{4})-(\d{2})-(\d{2})_\d{2}-\d{2}-\d{2}\.7z$'
                        foreach ($arch in $allArchives) {
                            $m = [regex]::Match($arch.Name, $pattern)
                            if (-not $m.Success) { continue }
                            $archDate = Get-Date -Year $m.Groups[1].Value -Month $m.Groups[2].Value -Day $m.Groups[3].Value -Hour 0 -Minute 0 -Second 0
                            if ($archDate -lt $cutoffDate) {
                                try {
                                    Remove-Item -LiteralPath $arch.FullName -Force
                                    $deletedCount++
                                    Write-Log "Ротация: удалён архив $($arch.Name)"
                                    Invoke-Db "INSERT INTO rotation_events (run_id, action, archive_name, cutoff_date)
                                               VALUES (@run, 'deleted', @a, @c)" @{ run = $runId; a = $arch.Name; c = $cutoffDate.ToString('yyyy-MM-dd') }
                                    # записи об этом архиве в БД больше не актуальны
                                    Invoke-Db 'DELETE FROM run_results WHERE archive_name = @a;' @{ a = $arch.Name }
                                }
                                catch {
                                    Write-Log "Ротация: не удалось удалить $($arch.Name): $($_.Exception.Message)" WARN
                                    Invoke-Db "INSERT INTO rotation_events (run_id, action, archive_name, cutoff_date, detail)
                                               VALUES (@run, 'delete_failed', @a, @c, @d)" @{ run = $runId; a = $arch.Name; c = $cutoffDate.ToString('yyyy-MM-dd'); d = $_.Exception.Message }
                                }
                            }
                        }
                    }
                    Write-Log ("Ротация: удалено архивов - {0} (старше {1:dd.MM.yyyy})." -f $deletedCount, $cutoffDate)
                }

                $completed = $true
            }
        }
        finally {
            # очистка временных файлов: и при нормальном завершении, и при прерывании
            if ($tempRoot -and (Test-Path -LiteralPath $tempRoot)) {
                Remove-Item -LiteralPath $tempRoot -Recurse -Force -ErrorAction SilentlyContinue
            }
        }

        # --- Итоги ---
        $sync.Aborted = $aborted
        if ($completed) {
            Write-Log "Готово. Успешно: $ok, с ошибками: $failed. Лог: $logPath" OK
            $sync.ExitCode = if ($failed -gt 0) { 2 } else { 0 }
        }
        elseif ($aborted) {
            Write-Log "ВЫПОЛНЕНИЕ ПРЕРВАНО: обработаны не все базы. Успешно: $ok, с ошибками: $failed. Временные файлы удалены." ERROR
            $sync.ExitCode = 3
        }

        if ($dbConn) {
            try {
                $status = if ($completed) { if ($failed -gt 0) { 'partial' } else { 'ok' } } else { 'aborted' }
                Invoke-Db "UPDATE runs SET finished_at = datetime('now','localtime'), status = @st,
                           ok_count = @ok, failed_count = @f, exit_code = @ex WHERE id = @id" @{
                    st = $status; ok = $ok; f = $failed; ex = $sync.ExitCode; id = $runId }
            }
            catch { Write-Log "SQLite: не удалось зафиксировать итог запуска: $($_.Exception.Message)" WARN }
            try { $dbConn.Close() } catch { }
        }
    }
    catch {
        Write-Log "ВНУТРЕННЯЯ ОШИБКА: $($_.Exception.Message)" ERROR
        $sync.FatalError = $true
        $sync.ExitCode = 1
        $fatalReason = $_.Exception.Message
    }
    finally {
        # Ротация текстовых логов: после прогона остаётся только лог текущего бэкапа
        # (SQLite-база backup_log.db со всей историей не трогается)
        try {
            $oldLogs = @(Get-ChildItem -LiteralPath $destination -Filter 'backup_*.log' -File -ErrorAction SilentlyContinue |
                Where-Object { $_.FullName -ne $logPath })
            if ($oldLogs.Count -gt 0) {
                foreach ($f in $oldLogs) { Remove-Item -LiteralPath $f.FullName -Force -ErrorAction SilentlyContinue }
                Write-Log ("Логи: удалено предыдущих - {0}, оставлен только текущий ({1})." -f $oldLogs.Count, (Split-Path -Leaf $logPath))
            }
        } catch { }
        $sync.Ok = $ok
        $sync.Failed = $failed
        # ntfy: итоговый push (единая точка на все исходы, включая ранние фатальные return)
        Send-NtfyRunSummary -Config $config -ConfigPath $sync.ConfigPath -OkCnt $ok -FailedCnt $failed `
            -Aborted $aborted -Fatal ($sync.FatalError -eq $true) -FatalText $fatalReason -RunRows $runRows
        $sync.Done = $true
    }
}

# --- Управление фоновым запуском ---------------------------------------------------
$script:running = $false
$script:ps = $null; $script:rs = $null; $script:handle = $null; $script:sync = $null

function Start-BackupRun {
    param($Config)

    $script:sync = [hashtable]::Synchronized(@{})
    $script:sync.Config     = $Config
    $script:sync.ConfigPath = $ConfigPath
    $script:sync.AppDir     = $appDir
    $script:sync.EmbeddedSqlite = $null
    if ($embeddedSqliteManagedFx -or $embeddedSqliteManagedCore) {
        $script:sync.EmbeddedSqlite = @{
            ManagedFx   = $embeddedSqliteManagedFx
            InteropFx   = $embeddedSqliteInteropFx
            ManagedCore = $embeddedSqliteManagedCore
            InteropCore = $embeddedSqliteInteropCore
        }
    }
    $script:sync.LogQueue   = [System.Collections.ArrayList]::Synchronized((New-Object System.Collections.ArrayList))
    $script:sync.LogPath    = $null
    $script:sync.Phase      = 'Подготовка'
    $script:sync.Total      = 0
    $script:sync.Progress   = 0
    $script:sync.Ok         = 0
    $script:sync.Failed     = 0
    $script:sync.CancelRequested = $false
    $script:sync.Aborted    = $false
    $script:sync.FatalError = $false
    $script:sync.ExitCode   = $null
    $script:sync.Done       = $false

    $script:rs = [runspacefactory]::CreateRunspace()
    $script:rs.Open()
    $script:ps = [powershell]::Create()
    $script:ps.Runspace = $script:rs
    [void]$script:ps.AddScript($script:backupWorker.ToString()).AddArgument($script:sync)
    $script:handle = $script:ps.BeginInvoke()
    $script:running = $true

    $BtnStart.IsEnabled = $false
    $BtnStop.IsEnabled = $true
    $BtnSettings.IsEnabled = $false
    $PhaseText.Foreground = $brushInfo
    $Progress.Foreground = $brushBar
    Add-UiMsg 'Запуск бэкапа (кнопка СТАРТ)' 'INFO'
}

function Complete-BackupRun {
    try { $null = $script:ps.EndInvoke($script:handle) }
    catch { Add-UiMsg "Внутренняя ошибка воркера: $($_.Exception.Message)" 'ERROR' }
    finally {
        try { $script:ps.Dispose() } catch { }
        try { $script:rs.Dispose() } catch { }
    }
    $script:running = $false

    $ok = $script:sync.Ok; $failed = $script:sync.Failed
    if ($script:sync.FatalError -or $script:sync.ExitCode -eq 1) {
        $PhaseText.Text = "ОШИБКА ЗАПУСКА — см. лог (успешно: $ok, с ошибками: $failed)"
        $PhaseText.Foreground = $brushErr
        $Progress.Foreground = $brushErr
        [System.Media.SystemSounds]::Exclamation.Play()
    }
    elseif ($script:sync.Aborted) {
        $PhaseText.Text = "ПРЕРВАНО. Успешно: $ok, с ошибками: $failed"
        $PhaseText.Foreground = $brushErr
        [System.Media.SystemSounds]::Exclamation.Play()
    }
    elseif ($failed -gt 0) {
        $PhaseText.Text = "Готово с ошибками. Успешно: $ok, с ошибками: $failed"
        $PhaseText.Foreground = $brushWarn
        $Progress.Foreground = $brushWarn
        [System.Media.SystemSounds]::Exclamation.Play()
    }
    else {
        $PhaseText.Text = "Готово. Успешно: $ok, с ошибками: $failed"
        $PhaseText.Foreground = $brushOk
        [System.Media.SystemSounds]::Asterisk.Play()
    }

    $BtnStart.IsEnabled = $true
    $BtnStop.IsEnabled = $false
    $BtnSettings.IsEnabled = $true
}

# --- Окно настроек (config.json) ---------------------------------------------------
$settingsXamlTemplate = @'
<Window xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation"
        xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml"
        Title="T-REX бэкап файловых баз 1С — настройки" Width="720" Height="800" MinWidth="560" MinHeight="560"
        WindowStartupLocation="CenterOwner" ShowInTaskbar="False"
        Background="#FF1E1E26" FontFamily="Segoe UI">
  <Window.Resources>
__STYLES__
    <Style x:Key="DarkBox" TargetType="TextBox">
      <Setter Property="Background" Value="#FF14141C"/>
      <Setter Property="Foreground" Value="#FFE6E6EB"/>
      <Setter Property="BorderBrush" Value="#FF3A3A4C"/>
      <Setter Property="BorderThickness" Value="1"/>
      <Setter Property="Padding" Value="4,3"/>
      <Setter Property="FontSize" Value="12"/>
      <Setter Property="VerticalContentAlignment" Value="Center"/>
    </Style>
    <Style x:Key="FieldLabel" TargetType="TextBlock">
      <Setter Property="Foreground" Value="#FFAFC4E8"/>
      <Setter Property="FontSize" Value="12"/>
      <Setter Property="VerticalAlignment" Value="Center"/>
    </Style>
    <Style x:Key="HintText" TargetType="TextBlock">
      <Setter Property="Foreground" Value="#FF70708C"/>
      <Setter Property="FontSize" Value="11"/>
    </Style>
  </Window.Resources>
  <Grid Margin="14">
    <Grid.RowDefinitions>
      <RowDefinition Height="Auto"/>
      <RowDefinition Height="Auto"/>
      <RowDefinition Height="Auto"/>
      <RowDefinition Height="Auto"/>
      <RowDefinition Height="Auto"/>
      <RowDefinition Height="Auto"/>
      <RowDefinition Height="Auto"/>
      <RowDefinition Height="Auto"/>
      <RowDefinition Height="*"/>
      <RowDefinition Height="Auto"/>
      <RowDefinition Height="Auto"/>
      <RowDefinition Height="Auto"/>
    </Grid.RowDefinitions>

    <StackPanel Grid.Row="0" Margin="0,0,0,10" Orientation="Horizontal">
      <TextBlock Text="Настройки бэкапа" FontSize="15" FontWeight="Bold" Foreground="#FF7FB4FF" VerticalAlignment="Center"/>
      <TextBlock x:Name="CfgHint" Style="{StaticResource HintText}" VerticalAlignment="Center"
                 Margin="10,3,0,0" TextTrimming="CharacterEllipsis" MaxWidth="420"/>
    </StackPanel>

    <Grid Grid.Row="1" Margin="0,0,0,6">
      <Grid.ColumnDefinitions>
        <ColumnDefinition Width="180"/><ColumnDefinition Width="*"/><ColumnDefinition Width="Auto"/>
      </Grid.ColumnDefinitions>
      <TextBlock Text="Папка для архивов" Style="{StaticResource FieldLabel}"/>
      <TextBox x:Name="DestBox" Grid.Column="1" Style="{StaticResource DarkBox}"/>
      <Button x:Name="DestBrowse" Grid.Column="2" Content="..." Style="{StaticResource NeutralBtn}" MinWidth="36" Margin="4,0,0,0"/>
    </Grid>

    <Grid Grid.Row="2" Margin="0,0,0,6">
      <Grid.ColumnDefinitions>
        <ColumnDefinition Width="180"/><ColumnDefinition Width="Auto"/><ColumnDefinition Width="*"/>
      </Grid.ColumnDefinitions>
      <TextBlock Text="Дней хранения архивов" Style="{StaticResource FieldLabel}"/>
      <TextBox x:Name="DaysBox" Grid.Column="1" Width="70" Style="{StaticResource DarkBox}"/>
      <TextBlock Grid.Column="2" Text="0 = не удалять старые архивы" Style="{StaticResource HintText}"
                 VerticalAlignment="Center" Margin="8,0,0,0"/>
    </Grid>

    <Grid Grid.Row="3" Margin="0,0,0,6">
      <Grid.ColumnDefinitions>
        <ColumnDefinition Width="180"/><ColumnDefinition Width="*"/><ColumnDefinition Width="Auto"/>
      </Grid.ColumnDefinitions>
      <TextBlock Text="7-Zip (путь к 7z.exe)" Style="{StaticResource FieldLabel}"
                 ToolTip="Необязательно. Если пусто — автопоиск: Program Files, затем PATH."/>
      <TextBox x:Name="ZipBox" Grid.Column="1" Style="{StaticResource DarkBox}"
               ToolTip="Пусто = искать автоматически (Program Files, PATH)"/>
      <Button x:Name="ZipBrowse" Grid.Column="2" Content="..." Style="{StaticResource NeutralBtn}" MinWidth="36" Margin="4,0,0,0"/>
    </Grid>

    <Grid Grid.Row="4" Margin="0,0,0,6">
      <Grid.ColumnDefinitions>
        <ColumnDefinition Width="180"/><ColumnDefinition Width="*"/><ColumnDefinition Width="Auto"/>
      </Grid.ColumnDefinitions>
      <TextBlock Text="Каталог временных копий" Style="{StaticResource FieldLabel}"
                 ToolTip="Куда копируются базы перед упаковкой в архив. Пусто = системный %TEMP% (обычно на диске C:). Укажите диск, где хватает места под копию самой большой базы."/>
      <TextBox x:Name="TempBox" Grid.Column="1" Style="{StaticResource DarkBox}"
               ToolTip="Пусто = системный %TEMP%. Пример: E:\Temp"/>
      <Button x:Name="TempBrowse" Grid.Column="2" Content="..." Style="{StaticResource NeutralBtn}" MinWidth="36" Margin="4,0,0,0"/>
    </Grid>

    <Grid Grid.Row="5" Margin="0,0,0,6">
      <Grid.ColumnDefinitions>
        <ColumnDefinition Width="180"/><ColumnDefinition Width="*"/><ColumnDefinition Width="Auto"/>
      </Grid.ColumnDefinitions>
      <CheckBox x:Name="LogSqliteBox" Content="БД логов (SQLite)" Foreground="#FFAFC4E8" FontSize="12"
                VerticalAlignment="Center"
                ToolTip="Выключено — прогон не пишет ничего в backup_log.db (остаётся только текстовый лог); поле пути ниже не используется"/>
      <TextBox x:Name="DbBox" Grid.Column="1" Style="{StaticResource DarkBox}"
               ToolTip="Пусто = &lt;папка архивов&gt;\backup_log.db. Для записи нужен System.Data.SQLite.dll рядом со скриптом или модуль PSSQLite."/>
      <Button x:Name="DbBrowse" Grid.Column="2" Content="..." Style="{StaticResource NeutralBtn}" MinWidth="36" Margin="4,0,0,0"/>
    </Grid>

    <GroupBox Grid.Row="6" Header="Push-уведомления ntfy (итог прогона на телефон)"
              Margin="0,4,0,6" BorderBrush="#FF3A3A4C" Foreground="#FFAFC4E8" FontSize="12">
      <Grid Margin="6">
        <Grid.ColumnDefinitions>
          <ColumnDefinition Width="180"/><ColumnDefinition Width="*"/><ColumnDefinition Width="Auto"/>
        </Grid.ColumnDefinitions>
        <Grid.RowDefinitions>
          <RowDefinition Height="Auto"/>
          <RowDefinition Height="Auto"/>
          <RowDefinition Height="Auto"/>
          <RowDefinition Height="Auto"/>
          <RowDefinition Height="Auto"/>
          <RowDefinition Height="Auto"/>
          <RowDefinition Height="Auto"/>
        </Grid.RowDefinitions>
        <CheckBox x:Name="NtfyEnabled" Grid.Row="0" Grid.ColumnSpan="3" Margin="0,0,0,6"
                  Content="Отправлять итог прогона (успех — тихо, ошибки — громко)" Foreground="#FFE6E6EB"/>
        <StackPanel Grid.Row="1" Grid.ColumnSpan="3" Orientation="Horizontal" Margin="0,0,0,6"
                    ToolTip="Способ доставки в ntfy (WebSocket-отправки в ntfy не существует — publish только по HTTP; оба способа проверены на нашем сервере)">
          <TextBlock Text="Способ:" Style="{StaticResource FieldLabel}" Margin="0,0,8,0" VerticalAlignment="Center"/>
          <RadioButton x:Name="NtfyModeJson" GroupName="NtfyMode" IsChecked="True" Margin="0,0,14,0"
                       Foreground="#FFE6E6EB" VerticalAlignment="Center" Content="JSON на корень"
                       ToolTip="POST на корень сервера: все параметры в JSON-теле (title, priority, теги). Основной способ."/>
          <RadioButton x:Name="NtfyModeTopic" GroupName="NtfyMode" Foreground="#FFE6E6EB" VerticalAlignment="Center"
                       Content="POST на топик (curl-стиль)"
                       ToolTip="POST прямо на топик: тело — простой текст, приоритет и теги — заголовками X-Priority/X-Tags (как curl). Запасной способ, заголовок уходит первой строкой текста."/>
        </StackPanel>
        <Grid Grid.Row="2" Grid.ColumnSpan="3" Margin="0,0,0,6"
              ToolTip="Период приёмки после установки: сколько дней от ПЕРВОГО прогона слать итоги (при внедрении у заказчика достаточно 10 дней наблюдения, затем уведомления сами отключатся). 0 или пусто = бессрочно. «Продлить с сегодня» перезапускает отсчёт (применится при сохранении).">
          <Grid.ColumnDefinitions>
            <ColumnDefinition Width="180"/><ColumnDefinition Width="Auto"/><ColumnDefinition Width="Auto"/><ColumnDefinition Width="*"/>
          </Grid.ColumnDefinitions>
          <TextBlock Text="Дней наблюдения" Style="{StaticResource FieldLabel}"/>
          <TextBox x:Name="NtfyWatchDaysBox" Grid.Column="1" Width="70" Style="{StaticResource DarkBox}" Margin="0,0,8,0"/>
          <Button x:Name="NtfyRenewBtn" Grid.Column="2" Content="Продлить с сегодня" Style="{StaticResource NeutralBtn}" Margin="0,0,8,0"
                  ToolTip="Отсчёт периода начнётся заново с сегодняшнего дня (количество дней — из поля слева). Применится при сохранении настроек."/>
          <TextBlock x:Name="NtfyWatchStatus" Grid.Column="3" Style="{StaticResource HintText}"
                     VerticalAlignment="Center" TextTrimming="CharacterEllipsis"/>
        </Grid>
        <TextBlock Grid.Row="3" Text="Сервер (URL)" Style="{StaticResource FieldLabel}"
                   ToolTip="Адрес ntfy-сервера, например http://11.22.33.44:2586"/>
        <TextBox x:Name="NtfyUrlBox" Grid.Row="3" Grid.Column="1" Grid.ColumnSpan="2" Style="{StaticResource DarkBox}"
                 ToolTip="Например: http://11.22.33.44:2586"/>
        <TextBlock Grid.Row="4" Text="Топик" Style="{StaticResource FieldLabel}"/>
        <TextBox x:Name="NtfyTopicBox" Grid.Row="4" Grid.Column="1" Grid.ColumnSpan="2" Style="{StaticResource DarkBox}"/>
        <Grid Grid.Row="5" Grid.ColumnSpan="3">
          <Grid.ColumnDefinitions>
            <ColumnDefinition Width="180"/><ColumnDefinition Width="*"/><ColumnDefinition Width="140"/><ColumnDefinition Width="Auto"/>
          </Grid.ColumnDefinitions>
          <TextBlock Text="Логин / пароль" Style="{StaticResource FieldLabel}"/>
          <TextBox x:Name="NtfyUserBox" Grid.Column="1" Style="{StaticResource DarkBox}" Margin="0,2,6,2"/>
          <PasswordBox x:Name="NtfyPwdBox" Grid.Column="2" Margin="0,2,6,2"
                       Background="#FF14141C" Foreground="#FFE6E6EB" BorderBrush="#FF3A3A4C"
                       BorderThickness="1" Padding="4,3" FontSize="12" VerticalContentAlignment="Center"
                       ToolTip="Хранится DPAPI-шифрованием под вашу учётку. Пусто = сохранённый ранее пароль"/>
          <Button x:Name="NtfyTestBtn" Grid.Column="3" Content="Отправить тест" Style="{StaticResource NeutralBtn}"/>
        </Grid>
        <TextBlock x:Name="NtfyTestText" Grid.Row="6" Grid.ColumnSpan="3" Style="{StaticResource HintText}"
                   TextWrapping="Wrap" Margin="0,4,0,0"/>
      </Grid>
    </GroupBox>

    <DockPanel Grid.Row="7" Margin="0,8,0,2">
      <StackPanel DockPanel.Dock="Right" Orientation="Horizontal">
        <Button x:Name="PathBtn" Content="Обзор пути" Style="{StaticResource NeutralBtn}"/>
        <Button x:Name="DelBtn" Content="- Удалить" Style="{StaticResource FlatBtn}"/>
        <Button x:Name="AddBtn" Content="+ Добавить" Style="{StaticResource GoBtn}"/>
      </StackPanel>
      <TextBlock Text="Базы 1С: имя для архива + путь (каталог базы или файл 1Cv8.1CD)"
                 Style="{StaticResource FieldLabel}"/>
    </DockPanel>

    <DataGrid x:Name="BasesGrid" Grid.Row="8" Margin="0,4" AutoGenerateColumns="False"
              CanUserAddRows="False" CanUserDeleteRows="False" CanUserReorderColumns="False"
              HeadersVisibility="Column" GridLinesVisibility="Horizontal" SelectionMode="Single"
              Background="#FF14141C" RowBackground="#FF20202C" AlternatingRowBackground="#FF24242F"
              Foreground="#FFE6E6EB" BorderBrush="#FF33334A" BorderThickness="1"
              HorizontalGridLinesBrush="#FF2C2C3C" FontSize="12">
      <DataGrid.ColumnHeaderStyle>
        <Style TargetType="DataGridColumnHeader">
          <Setter Property="Background" Value="#FF2E2E3E"/>
          <Setter Property="Foreground" Value="#FFAFC4E8"/>
          <Setter Property="FontWeight" Value="Bold"/>
          <Setter Property="Padding" Value="8,4"/>
          <Setter Property="BorderBrush" Value="#FF3A3A4C"/>
        </Style>
      </DataGrid.ColumnHeaderStyle>
      <DataGrid.Columns>
        <DataGridTextColumn Header="Имя для архива" Binding="{Binding Name}" Width="180"/>
        <DataGridTextColumn Header="Путь к базе (каталог или 1Cv8.1CD)" Binding="{Binding Path}" Width="*"/>
      </DataGrid.Columns>
    </DataGrid>

    <TextBlock x:Name="MsgText" Grid.Row="9" Foreground="#FFFF7676" TextWrapping="Wrap"
               Margin="0,8,0,0" FontSize="11"/>

    <UniformGrid Grid.Row="10" Columns="3" Margin="0,10,0,0">
      <Button x:Name="SchBtn" Content="Расписание…" Style="{StaticResource NeutralBtn}" FontSize="13"
              Padding="0,8" ToolTip="Задача Планировщика Windows: тихий бэкап по расписаниям (-Silent); расписаний может быть несколько"/>
      <Button x:Name="SaveBtn" Content="Сохранить" Style="{StaticResource GoBtn}" FontSize="13"
              FontWeight="Bold" Padding="0,8" IsDefault="True"/>
      <Button x:Name="CancelBtn" Content="Отмена" Style="{StaticResource FlatBtn}" FontSize="13"
              Padding="0,8" IsCancel="True"/>
    </UniformGrid>

    <TextBlock x:Name="AuthorText" Grid.Row="11" Style="{StaticResource HintText}"
               HorizontalAlignment="Center" Margin="0,10,0,0"/>
  </Grid>
</Window>
'@

# --- Окно расписания (задача Планировщика Windows для тихого бэкапа) ---------------
# Несколько расписаний: каждое = время + дни недели, все живут триггерами ОДНОЙ задачи.
