      <RowDefinition Height="Auto"/>
      <RowDefinition Height="Auto"/>
    </Grid.RowDefinitions>

    <TextBlock Grid.Row="0" Text="Расписания бэкапа (Планировщик Windows)" FontSize="15" FontWeight="Bold"
               Foreground="#FF7FB4FF" Margin="0,0,0,6"/>

    <TextBlock Grid.Row="1" Style="{StaticResource HintText}" TextWrapping="Wrap" Margin="0,0,0,10"
               Text="Задача Планировщика в заданные времена запускает тихий бэкап всех баз из config.json — без открытия окна, с обычными логами (backup_*.log и backup_log.db в папке архивов). Расписаний может быть несколько — например, 03:00 ежедневно и 15:30 по рабочим дням. Любое действие со списком («Добавить», «Изменить», «Удалить выбранное») сразу применяется к задаче Планировщика. Задача выполняется от текущего пользователя, пока компьютер включён."/>

    <TextBlock Grid.Row="2" Text="Список расписаний (время · дни)" Style="{StaticResource FieldLabel}"
               Margin="0,0,0,4"/>

    <ListBox x:Name="SchList" Grid.Row="3" Style="{StaticResource DarkList}"
             ItemContainerStyle="{StaticResource DarkListItem}" DisplayMemberPath="Display"/>

    <Border Grid.Row="4" BorderBrush="#FF33334A" BorderThickness="1" Background="#FF191922"
            Padding="10" Margin="0,10,0,0">
      <UniformGrid Columns="3">
        <Button x:Name="SchAddBtn" Content="Добавить" Style="{StaticResource NeutralBtn}" FontSize="12"
                Padding="0,6" ToolTip="Открыть окно нового расписания и добавить его в задачу"/>
        <Button x:Name="SchEditBtn" Content="Изменить" Style="{StaticResource NeutralBtn}" FontSize="12"
                Padding="0,6" ToolTip="Открыть окно правки выбранного расписания"/>
        <Button x:Name="SchDelBtn" Content="Удалить выбранное" Style="{StaticResource FlatBtn}" FontSize="12"
                Padding="0,6" ToolTip="Убрать выбранную строку из задачи"/>
      </UniformGrid>
    </Border>

    <TextBlock x:Name="SchCmdText" Grid.Row="5" Style="{StaticResource HintText}" TextWrapping="Wrap"
               Margin="0,10,0,0"/>

    <TextBlock x:Name="SchMsg" Grid.Row="6" Foreground="#FFFF7676" TextWrapping="Wrap"
               Margin="0,8,0,0" FontSize="11"/>

    <UniformGrid Grid.Row="7" Columns="2" Margin="0,10,0,0">
      <Button x:Name="SchRemoveBtn" Content="Удалить задачу" Style="{StaticResource FlatBtn}" FontSize="13"
              Padding="0,8"/>
      <Button x:Name="SchCloseBtn" Content="Закрыть" Style="{StaticResource NeutralBtn}" FontSize="13"
              Padding="0,8" IsCancel="True"/>
    </UniformGrid>
  </Grid>
</Window>
'@

# --- Диалог добавления/изменения одного расписания (время + дни недели) -------------
