    <TextBlock x:Name="TitleText" Grid.Row="0" Text="Новое расписание" FontSize="14" FontWeight="Bold"
               Foreground="#FF7FB4FF" Margin="0,0,0,8"/>

    <Grid Grid.Row="1" Margin="0,0,0,8">
      <Grid.ColumnDefinitions>
        <ColumnDefinition Width="170"/><ColumnDefinition Width="Auto"/>
      </Grid.ColumnDefinitions>
      <TextBlock Text="Время запуска (ЧЧ:ММ)" Style="{StaticResource FieldLabel}"/>
      <TextBox x:Name="SchTimeBox" Grid.Column="1" Width="80" Style="{StaticResource DarkBox}" Text="03:00"/>
    </Grid>

    <StackPanel Grid.Row="2" Margin="0,0,0,4">
      <TextBlock Text="Дни запуска" Style="{StaticResource FieldLabel}" Margin="0,0,0,2"/>
      <UniformGrid Columns="7">
        <CheckBox x:Name="DayMon" Content="Пн" Style="{StaticResource DarkCheck}" IsChecked="True"/>
        <CheckBox x:Name="DayTue" Content="Вт" Style="{StaticResource DarkCheck}" IsChecked="True"/>
        <CheckBox x:Name="DayWed" Content="Ср" Style="{StaticResource DarkCheck}" IsChecked="True"/>
        <CheckBox x:Name="DayThu" Content="Чт" Style="{StaticResource DarkCheck}" IsChecked="True"/>
        <CheckBox x:Name="DayFri" Content="Пт" Style="{StaticResource DarkCheck}" IsChecked="True"/>
        <CheckBox x:Name="DaySat" Content="Сб" Style="{StaticResource DarkCheck}" IsChecked="True"/>
        <CheckBox x:Name="DaySun" Content="Вс" Style="{StaticResource DarkCheck}" IsChecked="True"/>
