    <TextBlock x:Name="EditMsg" Grid.Row="3" Foreground="#FFFF7676" TextWrapping="Wrap"
               Margin="0,6,0,0" FontSize="11"/>

    <UniformGrid Grid.Row="4" Columns="2" Margin="0,10,0,0">
      <Button x:Name="OkBtn" Content="Сохранить" Style="{StaticResource GoBtn}" FontSize="13"
              FontWeight="Bold" Padding="0,8" IsDefault="True"/>
