function Build-SettingsWindow {
    param([string]$ConfigFile)

    $xaml = $settingsXamlTemplate.Replace('__STYLES__', $commonStyles)
    $rdr = New-Object System.Xml.XmlNodeReader ([xml]$xaml)
    $w2 = [Windows.Markup.XamlReader]::Load($rdr)

    $destBox = $w2.FindName('DestBox')
    $daysBox = $w2.FindName('DaysBox')
    $zipBox  = $w2.FindName('ZipBox')
    $tempBox = $w2.FindName('TempBox')
    $dbBox   = $w2.FindName('DbBox')
    $logSqliteBox = $w2.FindName('LogSqliteBox')
    $grid    = $w2.FindName('BasesGrid')
    $msgText = $w2.FindName('MsgText')
    $w2.Title = "$AppName — настройки"
    $w2.FindName('AuthorText').Text = "Автор: Валентин Суровцев, 2026 · версия $AppVersion"
    $w2.FindName('CfgHint').Text = "файл: $ConfigFile"

    $bases = New-Object System.Collections.ObjectModel.ObservableCollection[object]
    $grid.ItemsSource = $bases

    # существующий конфиг (если есть)
    $existing = $null
    if (Test-Path -LiteralPath $ConfigFile) {
        try { $existing = [IO.File]::ReadAllText($ConfigFile, $encUtf8) | ConvertFrom-Json } catch { $existing = $null }
    }
    if ($existing) {
        $destBox.Text = [string]$existing.Destination
        $daysBox.Text = "$($existing.KeepDays)"
        if ($null -eq $existing.KeepDays) { $daysBox.Text = "$($existing.КоличествоДнейАктуальности)" }
        $zipBox.Text  = [string]$existing.SevenZipPath
        $tempBox.Text = [string]$existing.TempDir
        $dbBox.Text   = [string]$existing.LogDb
        # флаг SQLite-лога: отсутствует в конфиге = включено (обратная совместимость)
        $logSqliteBox.IsChecked = ($existing.LogSqliteEnabled -ne $false)
        if ([string]::IsNullOrWhiteSpace($daysBox.Text)) { $daysBox.Text = '30' }
        foreach ($b in @($existing.Bases)) {
            [void]$bases.Add([pscustomobject]@{ Name = [string]$b.Name; Path = [string]$b.Path })
        }
        # ntfy (PasswordEnc не показываем: поле пароля пустое = «не менялся»)
        $ntfyCfg = $existing.Ntfy
        if ($ntfyCfg) {
            $w2.FindName('NtfyEnabled').IsChecked = ($ntfyCfg.Enabled -eq $true)
            $w2.FindName('NtfyUrlBox').Text   = [string]$ntfyCfg.Url
            $w2.FindName('NtfyTopicBox').Text = [string]$ntfyCfg.Topic
            $w2.FindName('NtfyUserBox').Text  = [string]$ntfyCfg.User
            # способ отправки: отсутствие/мусор в конфиге = json (обратная совместимость)
            if ([string]$ntfyCfg.Mode -eq 'topic') { $w2.FindName('NtfyModeTopic').IsChecked = $true }
            else { $w2.FindName('NtfyModeJson').IsChecked = $true }
        }
        if ([string]::IsNullOrWhiteSpace($w2.FindName('NtfyTopicBox').Text)) {
            $w2.FindName('NtfyTopicBox').Text = $NtfyDefaultTopic
        }
        # период наблюдения: поле — WatchDays (пусто = бессрочно), статус — по сохранённому конфигу
        if ($null -ne $existing.Ntfy.WatchDays) { $w2.FindName('NtfyWatchDaysBox').Text = "$($existing.Ntfy.WatchDays)" }
        $w2.FindName('NtfyWatchStatus').Text = Get-NtfyWatchStatusText -Ntfy $existing.Ntfy
    }
    else {
        $daysBox.Text = '30'
        $logSqliteBox.IsChecked = $true
        $w2.FindName('NtfyWatchDaysBox').Text = '10'
        $w2.FindName('NtfyWatchStatus').Text = Get-NtfyWatchStatusText -Ntfy $null
        $msgText.Text = 'Конфиг не найден — после сохранения он будет создан.'
    }
    # флаг «продлить срок» живёт в $global (закон GetNewClosure: $script: из обработчика снаружи не виден)
    $global:ntfyRenew = $false

    # флаг SQLite-лога управляет доступностью поля пути БД
    $updateDbEnabled = {
        $on = ($logSqliteBox.IsChecked -eq $true)
        $dbBox.IsEnabled = $on
        $w2.FindName('DbBrowse').IsEnabled = $on
    }.GetNewClosure()
    $logSqliteBox.Add_Checked($updateDbEnabled)
    $logSqliteBox.Add_Unchecked($updateDbEnabled)
    & $updateDbEnabled

    # галка ntfy управляет доступностью выбора способа отправки и полей срока наблюдения
    # (выбор — только при включённых пушах)
    $updateNtfyModeEnabled = {
        $on = ($w2.FindName('NtfyEnabled').IsChecked -eq $true)
        $w2.FindName('NtfyModeJson').IsEnabled = $on
        $w2.FindName('NtfyModeTopic').IsEnabled = $on
        $w2.FindName('NtfyWatchDaysBox').IsEnabled = $on
        $w2.FindName('NtfyRenewBtn').IsEnabled = $on
    }.GetNewClosure()
    $w2.FindName('NtfyEnabled').Add_Checked($updateNtfyModeEnabled)
    $w2.FindName('NtfyEnabled').Add_Unchecked($updateNtfyModeEnabled)
    & $updateNtfyModeEnabled

    # «Продлить с сегодня»: выставляет флаг для SaveBtn (отсчёт срока заново с сегодня)
    # и сразу показывает, какой срок получится; в конфиг пишется только при «Сохранить»
    $w2.FindName('NtfyRenewBtn').Add_Click({
        $wdTxtR = $w2.FindName('NtfyWatchDaysBox').Text.Trim()
        $wdR = 0
        if ($wdTxtR -match '^\d+$') { $wdR = [int]$wdTxtR }
        $stR = $w2.FindName('NtfyWatchStatus')
        if ($wdR -le 0) {
            $global:ntfyRenew = $true
            $stR.Text = 'будет бессрочно (0 дн.) — сохраните конфиг'
            return
        }
        $global:ntfyRenew = $true
        $stR.Text = ('будет: до {0:dd.MM.yyyy} ({1} дн. с сегодня) — сохраните конфиг' -f (Get-Date).Date.AddDays($wdR - 1), $wdR)
    }.GetNewClosure())

    # --- выбор папок/файлов ---
    $w2.FindName('DestBrowse').Add_Click({
        $dlg = New-Object System.Windows.Forms.FolderBrowserDialog
        $dlg.Description = 'Папка для архивов'
        $cur = $destBox.Text.Trim()
        if ($cur) { $xp = [Environment]::ExpandEnvironmentVariables($cur); if (Test-Path -LiteralPath $xp -PathType Container) { $dlg.SelectedPath = $xp } }
        if ($dlg.ShowDialog() -eq [System.Windows.Forms.DialogResult]::OK) { $destBox.Text = $dlg.SelectedPath }
    }.GetNewClosure())

    $w2.FindName('ZipBrowse').Add_Click({
        $dlg = New-Object System.Windows.Forms.OpenFileDialog
        $dlg.Filter = '7z.exe|7z.exe|Исполняемые файлы (*.exe)|*.exe'
        $dlg.FileName = '7z.exe'
        if ($zipBox.Text.Trim()) {
            $xp = [Environment]::ExpandEnvironmentVariables($zipBox.Text.Trim())
            if (Test-Path -LiteralPath $xp) { $dlg.InitialDirectory = (Split-Path -Parent $xp); $dlg.FileName = (Split-Path -Leaf $xp) }
        }
        if ($dlg.ShowDialog() -eq [System.Windows.Forms.DialogResult]::OK) { $zipBox.Text = $dlg.FileName }
    }.GetNewClosure())

    $w2.FindName('TempBrowse').Add_Click({
        $dlg = New-Object System.Windows.Forms.FolderBrowserDialog
        $dlg.Description = 'Каталог временных копий баз (пусто = системный %TEMP%)'
        $cur = $tempBox.Text.Trim()
        if ($cur) { $xp = [Environment]::ExpandEnvironmentVariables($cur); if (Test-Path -LiteralPath $xp -PathType Container) { $dlg.SelectedPath = $xp } }
        if ($dlg.ShowDialog() -eq [System.Windows.Forms.DialogResult]::OK) { $tempBox.Text = $dlg.SelectedPath }
    }.GetNewClosure())

    $w2.FindName('DbBrowse').Add_Click({
        $dlg = New-Object System.Windows.Forms.SaveFileDialog
        $dlg.Filter = 'SQLite БД (*.db)|*.db|Все файлы (*.*)|*.*'
        $dlg.FileName = 'backup_log.db'
        if ($dbBox.Text.Trim()) { $dlg.FileName = $dbBox.Text.Trim() }
        if ($dlg.ShowDialog() -eq [System.Windows.Forms.DialogResult]::OK) { $dbBox.Text = $dlg.FileName }
    }.GetNewClosure())

    # --- ntfy: тестовая отправка из введённых полей (сохранять конфиг не обязательно) ---
    $w2.FindName('NtfyTestBtn').Add_Click({
        $t = $w2.FindName('NtfyTestText')
        $t.Foreground = $w2.FindName('CfgHint').Foreground
        $url = $w2.FindName('NtfyUrlBox').Text.Trim()
        $topic = $w2.FindName('NtfyTopicBox').Text.Trim()
        $user = $w2.FindName('NtfyUserBox').Text.Trim()
        $pwdBox = $w2.FindName('NtfyPwdBox')
        if (-not $url -or -not $topic -or -not $user) { $t.Foreground = '#FFFF7676'; $t.Text = 'Заполните URL сервера, топик и логин.'; return }
        if ($url -notmatch '^https?://') { $t.Foreground = '#FFFF7676'; $t.Text = 'URL должен начинаться с http:// или https:// (без схемы ntfy-клиенты пробуют https — частая ловушка).'; return }
        $pass = $null
        if ($pwdBox.SecurePassword.Length -gt 0) {
            $bstr = [Runtime.InteropServices.Marshal]::SecureStringToBSTR($pwdBox.SecurePassword)
            try { $pass = [Runtime.InteropServices.Marshal]::PtrToStringBSTR($bstr) }
            finally { [Runtime.InteropServices.Marshal]::ZeroFreeBSTR($bstr) }
        }
        else { $pass = Get-NtfyPlainPassword ([string]$existing.Ntfy.PasswordEnc) }
        if (-not $pass) { $t.Foreground = '#FFFF7676'; $t.Text = 'Введите пароль (в поле пусто, сохранённого нет).'; return }
        $t.Text = 'Отправка…'
        $modeSel = 'json'
        if ($w2.FindName('NtfyModeTopic').IsChecked -eq $true) { $modeSel = 'topic' }
        try {
            Send-NtfyPush -Url $url -Topic $topic -User $user -Password $pass `
                -Title 'T-REX бэкап 1С: тест' -Message 'Тест из окна настроек — если видите это, канал работает.' `
                -Priority 'default' -Tags @('electric_plug') -Mode $modeSel
            $t.Foreground = '#FF7BD88A'
            $t.Text = "Отправлено ($topic, способ $modeSel) — проверьте телефон."
        }
        catch {
            $t.Foreground = '#FFFF7676'
            $t.Text = "Не удалось: $($_.Exception.Message)"
        }
    }.GetNewClosure())

    # --- таблица баз ---
    $w2.FindName('AddBtn').Add_Click({
        [void]$bases.Add([pscustomobject]@{ Name = ''; Path = '' })
        $grid.ScrollIntoView($bases[$bases.Count - 1])
        $grid.SelectedIndex = $bases.Count - 1
    }.GetNewClosure())

    $w2.FindName('DelBtn').Add_Click({
        $grid.CommitEdit([System.Windows.Controls.DataGridEditingUnit]::Row, $true)
        $sel = $grid.SelectedItem
        if ($sel) { $bases.Remove($sel) }
        else { $msgText.Text = 'Выберите строку базы в таблице.' }
    }.GetNewClosure())

    $w2.FindName('PathBtn').Add_Click({
        $grid.CommitEdit([System.Windows.Controls.DataGridEditingUnit]::Row, $true)
        $sel = $grid.SelectedItem
        if (-not $sel) { $msgText.Text = 'Выберите строку базы в таблице.'; return }
        $dlg = New-Object System.Windows.Forms.FolderBrowserDialog
        $dlg.Description = 'Каталог базы 1С (где лежит 1Cv8.1CD)'
        $cur = "$($sel.Path)".Trim()
        if ($cur) {
            $xp = [Environment]::ExpandEnvironmentVariables($cur)
            if (Test-Path -LiteralPath $xp -PathType Container) { $dlg.SelectedPath = $xp }
        }
        if ($dlg.ShowDialog() -eq [System.Windows.Forms.DialogResult]::OK) { $sel.Path = $dlg.SelectedPath }
    }.GetNewClosure())

    # --- отмена ---
    $w2.FindName('CancelBtn').Add_Click({ $w2.Close() }.GetNewClosure())

    # --- расписание: отдельное окно с задачей Планировщика ---
    $w2.FindName('SchBtn').Add_Click({
        $null = Show-ScheduleWindow -Owner $w2
    }.GetNewClosure())

    # --- сохранение ---
    $w2.FindName('SaveBtn').Add_Click({
        $msgText.Text = ''
        $errs = [System.Collections.Generic.List[string]]::new()

        # папка назначения
        $dest = [Environment]::ExpandEnvironmentVariables($destBox.Text.Trim())
        if (-not $dest) { $errs.Add('Укажите папку для архивов.') }
        elseif (-not (Test-Path -LiteralPath $dest -PathType Container)) {
            $r = [System.Windows.MessageBox]::Show($w2, "Папка '$dest' не существует. Создать?",
                                                   '$AppName — настройки', 'YesNo', 'Question')
            if ($r -eq 'Yes') {
                try { New-Item -ItemType Directory -Path $dest -Force | Out-Null }
                catch { $errs.Add("Не удалось создать папку: $($_.Exception.Message)") }
            }
            else { $errs.Add('Папка для архивов не существует.') }
        }

        # каталог временных копий (необязательно: пусто = системный %TEMP%)
        $tempDirVal = $tempBox.Text.Trim()
        if ($tempDirVal) {
            $tempDirVal = [Environment]::ExpandEnvironmentVariables($tempDirVal)
            if (-not (Test-Path -LiteralPath $tempDirVal -PathType Container)) {
                $rT = [System.Windows.MessageBox]::Show($w2, "Папка временных копий '$tempDirVal' не существует. Создать?",
                                                        '$AppName — настройки', 'YesNo', 'Question')
                if ($rT -eq 'Yes') {
                    try { New-Item -ItemType Directory -Path $tempDirVal -Force | Out-Null }
                    catch { $errs.Add("Не удалось создать папку временных копий: $($_.Exception.Message)") }
                }
                else { $errs.Add('Каталог временных копий не существует.') }
            }
        }

        # дни хранения
        $daysTxt = $daysBox.Text.Trim()
        if ($daysTxt -eq '') { $daysTxt = '30' }
        $keepDays = $null
        if ($daysTxt -match '^\d+$') { $keepDays = [int]$daysTxt }
        else { $errs.Add('«Дней хранения архивов» — целое число (0 = не удалять).') }

        # базы
        $grid.CommitEdit([System.Windows.Controls.DataGridEditingUnit]::Row, $true)
        $rows = [System.Collections.Generic.List[object]]::new()
        foreach ($o in $bases) {
            $n = "$($o.Name)".Trim()
            $p = "$($o.Path)".Trim()
            if ($n -eq '' -and $p -eq '') { continue }   # полностью пустые строки пропускаем
            if ($n -eq '') { $errs.Add('У базы не заполнено имя для архива.'); continue }
            if ($n -match '[\\/:\*\?"<>\|]') { $errs.Add("Имя «$n» содержит недопустимые для имени файла символы."); continue }
            if ($p -eq '') { $errs.Add("У базы «$n» не заполнен путь."); continue }
            $rows.Add([pscustomobject]@{ Name = $n; Path = $p })
        }
        if ($rows.Count -eq 0 -and $errs.Count -eq 0) { $errs.Add('Добавьте хотя бы одну базу.') }
        $dup = @($rows | Group-Object Name | Where-Object Count -gt 1)
        if ($dup.Count -gt 0) { $errs.Add('Дубликаты имён баз: ' + (($dup | ForEach-Object Name) -join ', ')) }

        # существование путей (предупреждение, не блокирующее сохранение)
        $notFound = [System.Collections.Generic.List[string]]::new()
        foreach ($row in $rows) {
            $xp = [Environment]::ExpandEnvironmentVariables($row.Path)
            if (Test-Path -LiteralPath $xp -PathType Leaf) {
                if ((Split-Path $xp -Leaf) -ne '1Cv8.1CD') { $errs.Add("Файл «$xp» должен называться 1Cv8.1CD.") }
            }
            elseif (-not (Test-Path -LiteralPath $xp -PathType Container)) {
                $notFound.Add($xp)
            }
        }

        if ($errs.Count -gt 0) { $msgText.Text = ($errs -join ' '); return }
        if ($notFound.Count -gt 0) {
            $r = [System.Windows.MessageBox]::Show($w2,
                "Пути не найдены:`n" + ($notFound -join "`n") + "`n`nСохранить конфиг всё равно? (при запуске эти базы будут отмечены как НЕ НАЙДЕННЫЕ)",
                '$AppName — настройки', 'YesNo', 'Warning')
            if ($r -ne 'Yes') { return }
        }

        $configOrdered = [ordered]@{
            Destination = $dest
            KeepDays = $keepDays
            Bases = $rows
        }
        $zipTxt = $zipBox.Text.Trim(); if ($zipTxt) { $configOrdered['SevenZipPath'] = $zipTxt }
        if ($tempDirVal) { $configOrdered['TempDir'] = $tempDirVal }
        $dbTxt  = $dbBox.Text.Trim();  if ($dbTxt)  { $configOrdered['LogDb'] = $dbTxt }
        $configOrdered['LogSqliteEnabled'] = ($w2.FindName('LogSqliteBox').IsChecked -eq $true)

        # --- ntfy: секция уведомлений ---
        $ntfyEnabled = ($w2.FindName('NtfyEnabled').IsChecked -eq $true)
        $ntfyUrl     = $w2.FindName('NtfyUrlBox').Text.Trim()
        $ntfyTopic   = $w2.FindName('NtfyTopicBox').Text.Trim()
        $ntfyUser    = $w2.FindName('NtfyUserBox').Text.Trim()
        $ntfyPwdBox  = $w2.FindName('NtfyPwdBox')
        # период наблюдения: 0/пусто = бессрочно
        $watchTxt = $w2.FindName('NtfyWatchDaysBox').Text.Trim()
        $watchDays = 0
        if ($watchTxt -match '^\d+$') { $watchDays = [int]$watchTxt }
        elseif ($watchTxt -ne '') { $errs.Add('ntfy: «Дней наблюдения» — целое число (0 = бессрочно).') }
        if ($ntfyEnabled) {
            if ($ntfyUrl -notmatch '^https?://') { $errs.Add('ntfy: URL сервера должен начинаться с http:// или https://.') }
            if (-not $ntfyTopic) { $errs.Add('ntfy: укажите топик.') }
            if (-not $ntfyUser)  { $errs.Add('ntfy: укажите логин.') }
        }
        if ($errs.Count -gt 0) { $msgText.Text = ($errs -join ' '); return }
        # пароль: введён -> DPAPI-шифруем; пусто -> сохраняем прежний (если был)
        $pwdEntered = ($ntfyPwdBox.SecurePassword.Length -gt 0)
        $ntfyPwdEnc = if ($pwdEntered) {
            ConvertFrom-SecureString $ntfyPwdBox.SecurePassword
        }
        else {
            if ($existing -and $existing.Ntfy) { [string]$existing.Ntfy.PasswordEnc } else { '' }
        }
        if ($ntfyEnabled -and -not $ntfyPwdEnc) {
            $msgText.Text = 'ntfy: введите пароль (в поле пароля пусто, сохранённого ранее нет).'
            return
        }
        if ($ntfyEnabled -or $ntfyUrl -or $ntfyTopic -or $ntfyUser -or $ntfyPwdEnc) {
            $ntfyMode = 'json'
            if ($w2.FindName('NtfyModeTopic').IsChecked -eq $true) { $ntfyMode = 'topic' }
            $ntfySection = [ordered]@{
                Enabled     = $ntfyEnabled
                Url         = $ntfyUrl
                Topic       = $ntfyTopic
                User        = $ntfyUser
                PasswordEnc = $ntfyPwdEnc
                Mode        = $ntfyMode
                WatchDays   = $watchDays
            }
            # состояние срока: «Продлить с сегодня» или ввод НОВОГО пароля (признак новой
            # установки) перезапускают отсчёт; иначе переносится прежнее состояние,
            # а при его отсутствии дату зафиксирует первый прогон (воркер)
            if ($watchDays -gt 0) {
                $prevNtfy = if ($existing) { $existing.Ntfy } else { $null }
                $restartWatch = ($global:ntfyRenew -eq $true) -or $pwdEntered
                if ($restartWatch) {
                    $ntfySection['ActiveUntil'] = (Get-Date).Date.AddDays($watchDays - 1).ToString('yyyy-MM-dd')
                    $ntfySection['FinalNoticeSent'] = $false
                }
                elseif ($prevNtfy) {
                    if ($prevNtfy.ActiveUntil) { $ntfySection['ActiveUntil'] = [string]$prevNtfy.ActiveUntil }
                    if ($null -ne $prevNtfy.FinalNoticeSent) { $ntfySection['FinalNoticeSent'] = [bool]$prevNtfy.FinalNoticeSent }
                }
            }
            $configOrdered['Ntfy'] = [pscustomobject]$ntfySection
        }

        try {
            $json = ConvertTo-Json ([pscustomobject]$configOrdered) -Depth 4
            [IO.File]::WriteAllText($ConfigFile, $json, $encUtf8)
        }
        catch {
            $msgText.Text = "Не удалось записать конфиг: $($_.Exception.Message)"
            return
        }
        [void][System.Windows.MessageBox]::Show($w2, "Конфиг сохранён:`n$ConfigFile",
                                                '$AppName — настройки', 'OK', 'Information')
        # именно $global: — $script: из GetNewClosure-обработчика пишет в скоуп замыкания
        # (динамический модуль) и снаружи НЕ ВИДЕН; $global: — общий для всего runspace
        $global:sSaved = $true
        $w2.Close()
    }.GetNewClosure())

    return $w2
}

function Show-SettingsWindow {
    param([string]$ConfigFile, $Owner)
    $global:sSaved = $false
    $w2 = Build-SettingsWindow -ConfigFile $ConfigFile
    if ($Owner) { $w2.Owner = $Owner }
    $null = $w2.ShowDialog()
    return $global:sSaved
}

# --- Задача Планировщика Windows для тихого бэкапа (-Silent) ------------------------

function Get-SelfScheduleAction {
    # что прописать в задачу: сам exe с -Silent; при запуске из .ps1 — текущая
    # оболочка (pwsh/powershell) с -File на этот скрипт
    if ($PSCommandPath) {
        $execute = (Get-Process -Id $PID).Path
        $arg = "-NoProfile -ExecutionPolicy Bypass -File `"$PSCommandPath`""
    }
    else {
        $execute = [Environment]::GetCommandLineArgs()[0]
        $arg = ''
    }
    $arg = ($arg + ' -Silent').Trim()
    # нестандартный путь конфига передаётся явно (по умолчанию берётся config.json рядом со скриптом)
    if ($ConfigPath -and ($ConfigPath -ne (Join-Path $appDir 'config.json'))) {
        $arg += " -ConfigPath `"$ConfigPath`""
    }
    return [pscustomobject]@{ Execute = $execute; Argument = $arg }
}

function Get-BackupScheduleState {
    # состояние существующей задачи: $null, если задачи нет; иначе массив расписаний,
    # каждое @{ Time = 'ЧЧ:ММ'; Days = @(1..7) } (Days — индексы 1=Пн..7=Вс; Daily-триггер = все 7 дней)
    try { $task = Get-ScheduledTask -TaskName $SchTaskName -ErrorAction Stop }
    catch { return $null }
    $result = @()
    foreach ($trig in @($task.Triggers)) {
        $state = @{ Time = '03:00'; Days = @(1, 2, 3, 4, 5, 6, 7) }
        if ($trig.StartBoundary -and ($trig.StartBoundary -match 'T(\d{2}:\d{2})')) {
            $state.Time = $Matches[1]
        }
        if ($trig.CimClass.CimClassName -match 'Weekly') {
            $mask = [int]$trig.DaysOfWeek
            if ($mask -gt 0) {
                $bitsByDay = @(2, 4, 8, 16, 32, 64, 1)   # Пн..Вс (битовая маска шедулера: Вс=1, Пн=2, ..., Сб=64)
                $days = @()
                for ($i = 0; $i -lt 7; $i++) { if ($mask -band $bitsByDay[$i]) { $days += ($i + 1) } }
                $state.Days = $days
            }
        }
        $result += $state
    }
    if ($result.Count -eq 0) { $result += @{ Time = '03:00'; Days = @(1, 2, 3, 4, 5, 6, 7) } }
    return ,$result
}

function Set-BackupScheduleTask {
    # каждое расписание становится своим триггером ОДНОЙ задачи шедулера
    param([object[]]$Schedules)   # элементы: @{ Time = 'ЧЧ:ММ'; Days = @(1=Пн..7=Вс) }

    $launch = Get-SelfScheduleAction
    $action = New-ScheduledTaskAction -Execute $launch.Execute -Argument $launch.Argument -WorkingDirectory $appDir
    $triggers = @()
    foreach ($s in $Schedules) {
        $at = [datetime]::ParseExact($s.Time, 'HH:mm', [Globalization.CultureInfo]::InvariantCulture)
        if (@($s.Days | Sort-Object -Unique).Count -eq 7) {
            $triggers += New-ScheduledTaskTrigger -Daily -At $at
        }
        else {
            $dows = @($s.Days | ForEach-Object { [System.DayOfWeek]($_ % 7) })   # 7 (Вс) -> 0 (Sunday)
            $triggers += New-ScheduledTaskTrigger -Weekly -DaysOfWeek $dows -At $at
        }
    }
    $settings = New-ScheduledTaskSettingsSet -StartWhenAvailable -AllowStartIfOnBatteries -DontStopIfGoingOnBatteries
    Register-ScheduledTask -TaskName $SchTaskName -Action $action -Trigger $triggers -Settings $settings `
        -Description "Тихий бэкап всех баз из config.json ($AppName v$AppVersion, автор Валентин Суровцев, 2026)" -Force | Out-Null
}

function Remove-BackupScheduleTask {
    Unregister-ScheduledTask -TaskName $SchTaskName -Confirm:$false -ErrorAction Stop
}

# --- Диалог одного расписания: результат — $global:scheduleEditResult ---------------
# ВАЖНО (два закона GetNewClosure-обработчиков):
# 1) локальные функции Build-* после её возврата НЕ СУЩЕСТВУЮТ — обработчики могут звать
#    только top-level функции (New-ScheduleItem, Update-ListButtons вынесены наверх);
# 2) запись $script:var из обработчика уходит в скоуп замыкания (динамический модуль)
#    и снаружи НЕ ВИДЕНА — результат диалога передаётся только через $global:var.

function New-ScheduleItem {
    # элемент списка расписаний: { Time; Days (1=Пн..7=Вс); Display } — Display показывает ListBox
    param([string]$Time, [int[]]$Days)
    $dayNames = @{ 1 = 'Пн'; 2 = 'Вт'; 3 = 'Ср'; 4 = 'Чт'; 5 = 'Пт'; 6 = 'Сб'; 7 = 'Вс' }
    $sorted = @($Days | Sort-Object -Unique)
    $daysText = if ($sorted.Count -eq 7) { 'ежедневно' }
                else { (@($sorted | ForEach-Object { $dayNames[$_] }) -join ' ') }
    [pscustomobject]@{ Time = $Time; Days = [int[]]$sorted; Display = "$Time · $daysText" }
}

function Update-ListButtons {
    # «Изменить» и «Удалить выбранное» доступны только при выбранной строке списка
    param($List, $EditBtn, $DelBtn)
    $has = ($null -ne $List.SelectedItem)
    $EditBtn.IsEnabled = $has
    $DelBtn.IsEnabled = $has
}

function Apply-ScheduleList {
    # сразу перерегистрировать задачу Планировщика по всему списку расписаний;
    # $true = успех (кисти передаются параметром: top-level функции их не видят)
    param($Schedules, $Msg, $BrushOk, $BrushErr, [string]$What)
    try {
        $toRegister = @($Schedules | ForEach-Object { @{ Time = $_.Time; Days = $_.Days } })
        Set-BackupScheduleTask -Schedules $toRegister
        $Msg.Foreground = $BrushOk
        $Msg.Text = "$What — задача обновлена: расписаний — $($Schedules.Count), тихий бэкап по указанным временам (запуск от текущего пользователя)."
        return $true
    }
    catch {
        $Msg.Foreground = $BrushErr
        $Msg.Text = "Не удалось обновить задачу: $($_.Exception.Message) — повторите действие (данные списка при этом сохранены)."
        return $false
    }
}

function Build-ScheduleEditWindow {
    param([string]$WindowTitle = 'Новое расписание', [string]$Time = '03:00', [int[]]$Days = @(1, 2, 3, 4, 5, 6, 7))

    $xaml = $scheduleEditXamlTemplate.Replace('__STYLES__', $commonStyles)
    $rdr = New-Object System.Xml.XmlNodeReader ([xml]$xaml)
    $w4 = [Windows.Markup.XamlReader]::Load($rdr)

    $w4.Title = "$AppName — $WindowTitle"
    $w4.FindName('TitleText').Text = $WindowTitle
    $timeBox = $w4.FindName('SchTimeBox')
    $msg     = $w4.FindName('EditMsg')
    # именно обычный hashtable: у [ordered] int-индекс $d[N] — это ПОЗИЦИЯ, а не ключ
    $dayBoxes = @{
        1 = $w4.FindName('DayMon'); 2 = $w4.FindName('DayTue'); 3 = $w4.FindName('DayWed')
        4 = $w4.FindName('DayThu'); 5 = $w4.FindName('DayFri'); 6 = $w4.FindName('DaySat')
        7 = $w4.FindName('DaySun')
    }
    $timeBox.Text = $Time
    foreach ($k in @($dayBoxes.Keys)) { $dayBoxes[$k].IsChecked = (@($Days) -contains [int]$k) }

    $w4.FindName('OkBtn').Add_Click({
        $msg.Foreground = $brushErr; $msg.Text = ''
        $time = "$($timeBox.Text)".Trim()
        if ($time -notmatch '^([01]?\d|2[0-3]):[0-5]\d$') {
            $msg.Text = 'Время укажите в формате ЧЧ:ММ, например 03:00.'; return
        }
        $days = @($dayBoxes.Keys | Where-Object { $dayBoxes[$_].IsChecked } | ForEach-Object { [int]$_ })
        if ($days.Count -eq 0) {
            $msg.Text = 'Отметьте хотя бы один день недели.'; return
        }
        $global:scheduleEditResult = @{ Time = $time; Days = $days }
        $w4.Close()
    }.GetNewClosure())

    $w4.FindName('CancelBtn').Add_Click({ $w4.Close() }.GetNewClosure())
    return $w4
}

function Show-ScheduleEditWindow {
    # возвращает $null (отмена) либо @{ Time = 'ЧЧ:ММ'; Days = @(1=Пн..7=Вс) }
    param($Owner, [string]$WindowTitle = 'Новое расписание', [string]$Time = '03:00', [int[]]$Days = @(1, 2, 3, 4, 5, 6, 7))
    $global:scheduleEditResult = $null
    $w4 = Build-ScheduleEditWindow -WindowTitle $WindowTitle -Time $Time -Days $Days
    if ($Owner) { $w4.Owner = $Owner }
    $null = $w4.ShowDialog()
    return $global:scheduleEditResult
}

function Build-ScheduleWindow {
    $xaml = $scheduleXamlTemplate.Replace('__STYLES__', $commonStyles)
    $rdr = New-Object System.Xml.XmlNodeReader ([xml]$xaml)
    $w3 = [Windows.Markup.XamlReader]::Load($rdr)

    $list    = $w3.FindName('SchList')
    $msg     = $w3.FindName('SchMsg')
    $addBtn  = $w3.FindName('SchAddBtn')
    $editBtn = $w3.FindName('SchEditBtn')
    $delBtn  = $w3.FindName('SchDelBtn')

    # элементы списка: pscustomobject { Time; Days; Display } в ObservableCollection
    $schedules = New-Object System.Collections.ObjectModel.ObservableCollection[object]
    $list.ItemsSource = $schedules

    # существующая задача -> список её расписаний (нет задачи — одно дефолтное: все дни, 03:00)
    $state = Get-BackupScheduleState
    if ($state) {
        foreach ($s in @($state)) { [void]$schedules.Add((New-ScheduleItem -Time $s.Time -Days $s.Days)) }
        $msg.Foreground = $brushOk
        $msg.Text = "Задача «$SchTaskName» уже есть в Планировщике — список загружен из неё; действия со списком применяются к задаче сразу."
    }
    else {
        [void]$schedules.Add((New-ScheduleItem -Time '03:00' -Days @(1, 2, 3, 4, 5, 6, 7)))
    }
    $list.SelectedIndex = 0

    # «Изменить» и «Удалить выбранное» доступны только при выбранной строке
    Update-ListButtons -List $list -EditBtn $editBtn -DelBtn $delBtn

    $list.Add_SelectionChanged({
        Update-ListButtons -List $list -EditBtn $editBtn -DelBtn $delBtn
    }.GetNewClosure())

    $launch = Get-SelfScheduleAction
    $w3.FindName('SchCmdText').Text = "Команда задачи: `"$($launch.Execute)`" $($launch.Argument)"

    $addBtn.Add_Click({
        $r = Show-ScheduleEditWindow -Owner $w3 -WindowTitle 'Новое расписание'
        if (-not $r) { return }
        $item = New-ScheduleItem -Time $r.Time -Days $r.Days
        [void]$schedules.Add($item)
        $list.SelectedIndex = $schedules.Count - 1
        $list.ScrollIntoView($item)
        Update-ListButtons -List $list -EditBtn $editBtn -DelBtn $delBtn
        $null = Apply-ScheduleList -Schedules $schedules -Msg $msg -BrushOk $brushOk -BrushErr $brushErr -What 'Расписание добавлено'
    }.GetNewClosure())

    $editBtn.Add_Click({
        $sel = $list.SelectedItem
        if (-not $sel) { return }
        $r = Show-ScheduleEditWindow -Owner $w3 -WindowTitle 'Изменение расписания' -Time $sel.Time -Days $sel.Days
        if (-not $r) { return }
        $idx = $list.SelectedIndex
        $schedules[$idx] = New-ScheduleItem -Time $r.Time -Days $r.Days
        $list.SelectedIndex = $idx
        Update-ListButtons -List $list -EditBtn $editBtn -DelBtn $delBtn
        $null = Apply-ScheduleList -Schedules $schedules -Msg $msg -BrushOk $brushOk -BrushErr $brushErr -What 'Расписание изменено'
    }.GetNewClosure())

    $delBtn.Add_Click({
        if (-not $list.SelectedItem) { return }
        $idx = $list.SelectedIndex
        $schedules.RemoveAt($idx)
        if ($schedules.Count -gt 0) {
            $list.SelectedIndex = [Math]::Min($idx, $schedules.Count - 1)
            Update-ListButtons -List $list -EditBtn $editBtn -DelBtn $delBtn
            $null = Apply-ScheduleList -Schedules $schedules -Msg $msg -BrushOk $brushOk -BrushErr $brushErr -What 'Расписание удалено'
        }
        else {
            Update-ListButtons -List $list -EditBtn $editBtn -DelBtn $delBtn
            $r = [System.Windows.MessageBox]::Show($w3,
                'Это было последнее расписание. Удалить задачу из Планировщика?',
                $AppName, 'YesNo', 'Question')
            if ($r -eq 'Yes') {
                try {
                    Remove-BackupScheduleTask
                    $msg.Foreground = $brushOk
                    $msg.Text = 'Задача удалена из Планировщика.'
                }
                catch {
                    $msg.Foreground = $brushErr
                    $msg.Text = "Не удалось удалить задачу: $($_.Exception.Message)"
                }
            }
            else {
                $msg.Foreground = $brushWarn
                $msg.Text = 'Задача оставлена в Планировщике — добавьте расписание, и она будет обновлена.'
            }
        }
    }.GetNewClosure())

    $w3.FindName('SchRemoveBtn').Add_Click({
        $msg.Foreground = $brushErr; $msg.Text = ''
        if (-not (Get-BackupScheduleState)) {
            $msg.Foreground = $brushWarn; $msg.Text = 'Задача не найдена — удалять нечего.'; return
        }
        try {
            Remove-BackupScheduleTask
            $msg.Foreground = $brushOk
            $msg.Text = 'Задача удалена из Планировщика.'
        }
        catch {
            $msg.Foreground = $brushErr
            $msg.Text = "Не удалось удалить задачу: $($_.Exception.Message)"
        }
    }.GetNewClosure())

    $w3.FindName('SchCloseBtn').Add_Click({ $w3.Close() }.GetNewClosure())
    return $w3
}

function Show-ScheduleWindow {
    param($Owner)
    $w3 = Build-ScheduleWindow
    $w3.Title = "$AppName — расписание"
    if ($Owner) { $w3.Owner = $Owner }
    $null = $w3.ShowDialog()
}

# --- Обработчики главного окна -----------------------------------------------------

$BtnStart.Add_Click({
    if ($script:running) { return }

    $LogBox.Document.Blocks.Clear()
    $PhaseText.Foreground = $brushInfo
    $PhaseText.Text = 'Чтение конфигурации…'
    $Progress.Value = 0; $Progress.Maximum = 1; $Progress.Foreground = $brushBar
    $CountersText.Text = 'Успешно: 0   Ошибки: 0'

    if (-not (Test-Path -LiteralPath $ConfigPath)) {
        Add-UiMsg "Конфиг не найден: $ConfigPath" 'WARN'
        $r = [System.Windows.MessageBox]::Show($win, "Конфиг не найден:`n$ConfigPath`n`nОткрыть настройки?",
                                                '$AppName', 'YesNo', 'Question')
        if ($r -eq 'Yes') { $null = Show-SettingsWindow -ConfigFile $ConfigPath -Owner $win }
        if (-not (Test-Path -LiteralPath $ConfigPath)) {
            $PhaseText.Text = 'Готов к запуску (нет конфига — нажмите ⚙)'
            return
        }
    }

    try { $cfg = [IO.File]::ReadAllText($ConfigPath, $encUtf8) | ConvertFrom-Json }
    catch {
        Add-UiMsg "Ошибка разбора конфига: $($_.Exception.Message)" 'ERROR'
        [void][System.Windows.MessageBox]::Show($win, "Ошибка разбора конфига: $($_.Exception.Message)",
                                                '$AppName', 'OK', 'Error')
        $PhaseText.Text = 'Ошибка конфига'
        return
    }

    if (-not $cfg.Destination -or -not $cfg.Bases -or @($cfg.Bases).Count -eq 0) {
        [void][System.Windows.MessageBox]::Show($win,
            'В конфиге должны быть заполнены Destination (папка архивов) и хотя бы одна база.',
            '$AppName', 'OK', 'Warning')
        $PhaseText.Text = 'Конфиг неполный — откройте настройки (⚙)'
        return
    }

    Start-BackupRun -Config $cfg
})

$BtnStop.Add_Click({
    if (-not $script:running) { return }
    $script:sync.CancelRequested = $true
    $BtnStop.IsEnabled = $false
    $PhaseText.Foreground = $brushWarn
    $PhaseText.Text = 'Остановка после текущей базы…'
})

$BtnSettings.Add_Click({
    if ($script:running) {
        [void][System.Windows.MessageBox]::Show($win, 'Остановите выполняемый бэкап перед изменением настроек.',
                                                '$AppName', 'OK', 'Warning')
        return
    }
    $saved = Show-SettingsWindow -ConfigFile $ConfigPath -Owner $win
    if ($saved) {
        $LogBox.Document.Blocks.Clear()
        $PhaseText.Text = 'Готов к запуску'
        Add-UiMsg "Настройки сохранены: $ConfigPath (будут прочитаны при старте)" 'INFO'
    }
})

$win.Add_Closing({
    param($sender, $e)
    if ($script:running) {
        $e.Cancel = $true
        $r = [System.Windows.MessageBox]::Show($win,
            'Бэкап ещё выполняется. Прервать и выйти?',
            '$AppName', 'YesNo', 'Warning')
        if ($r -eq 'Yes') {
            $script:sync.CancelRequested = $true
            # даём воркеру шанс корректно завершиться (обычно хватает мгновений)
            $deadline = (Get-Date).AddSeconds(8)
            while (-not $script:sync.Done -and (Get-Date) -lt $deadline) {
                Start-Sleep -Milliseconds 100
                [System.Windows.Forms.Application]::DoEvents()
            }
            if (-not $script:sync.Done) { try { $script:ps.Stop() } catch { } }
            $e.Cancel = $false
        }
    }
})

# --- Таймер обновления UI: сливает очередь лога воркера и отражает прогресс ---------
$uiTimer = New-Object System.Windows.Threading.DispatcherTimer
$uiTimer.Interval = [TimeSpan]::FromMilliseconds(250)
$uiTimer.Add_Tick({
    if ($null -ne $script:sync) {
        $q = $script:sync.LogQueue
        while ($q.Count -gt 0) {
            $item = $q[0]
            $q.RemoveAt(0)
            Add-UiLog $item.Line $item.Level
        }
        if ($script:sync.Phase) { $PhaseText.Text = $script:sync.Phase }
        if ($script:sync.Total -gt 0) { $Progress.Maximum = $script:sync.Total }
        $Progress.Value = $script:sync.Progress
        $CountersText.Text = ('Успешно: {0}   Ошибки: {1}' -f $script:sync.Ok, $script:sync.Failed)
        if ($script:sync.Done -and $script:running) { Complete-BackupRun }
    }
})

# --- Стартовые записи в лог ---------------------------------------------------------
if (-not $Silent) {
    Add-UiMsg "$AppName — GUI для backup-1c.ps1 (копирование → 7-Zip → ротация, SQLite-лог)" 'INFO'
    Add-UiMsg "Конфиг: $ConfigPath" 'INFO'
    if (-not (Test-Path -LiteralPath $ConfigPath)) {
        Add-UiMsg 'Конфиг не найден — нажмите ⚙ и заполните настройки.' 'WARN'
        $PhaseText.Text = 'Нет конфига — нажмите ⚙'
    }
}

# --- Режим проверки встроенного SQLite-драйвера (без показа окна) -------------------
if ($TestSqlite) {
    function ConvertFrom-GzipB64Local {
        param([string]$B64Text)
        $bytes = [Convert]::FromBase64String(($B64Text -replace '\s', ''))
        $inMs = [IO.MemoryStream]::new($bytes)
        $gz = [IO.Compression.GZipStream]::new($inMs, [IO.Compression.CompressionMode]::Decompress)
        $out = [IO.MemoryStream]::new()
        $gz.CopyTo($out)
        $gz.Dispose()
        $out.ToArray()
    }
    if (-not ($embeddedSqliteManagedFx -or $embeddedSqliteManagedCore)) {
        Write-Output 'НЕТ: встроенный драйвер отсутствует — сначала запустите make_embedded_sqlite.ps1'
        [Environment]::Exit(1)
    }
    if (-not [Environment]::Is64BitProcess) {
        Write-Output 'НЕТ: процесс 32-битный, встроенный драйвер только x64 (сработает запасной путь через PSSQLite).'
        [Environment]::Exit(1)
    }
    $pair = $null; $subDir = ''
    if ($PSVersionTable.PSEdition -eq 'Core') {
        $pair = @{ Managed = $embeddedSqliteManagedCore; Interop = $embeddedSqliteInteropCore }; $subDir = 'sqlite-x64-netcore'
    }
    else {
        $pair = @{ Managed = $embeddedSqliteManagedFx; Interop = $embeddedSqliteInteropFx }; $subDir = 'sqlite-x64-netfx'
    }
    $libDir = Join-Path ([Environment]::GetFolderPath('LocalApplicationData')) "T-REX-Backup1C\$subDir"
    New-Item -ItemType Directory -Path $libDir -Force | Out-Null
    foreach ($f in @(
        @{ File = (Join-Path $libDir 'System.Data.SQLite.dll'); Blob = $pair.Managed },
        @{ File = (Join-Path $libDir 'SQLite.Interop.dll');     Blob = $pair.Interop }
    )) {
        $bytes = ConvertFrom-GzipB64Local $f.Blob
        $fresh = if (Test-Path -LiteralPath $f.File) { (Get-Item -LiteralPath $f.File).Length -eq $bytes.Length } else { $false }
        if (-not $fresh) { [IO.File]::WriteAllBytes($f.File, $bytes) }
    }
    Add-Type -Path (Join-Path $libDir 'System.Data.SQLite.dll') -ErrorAction Stop
    if (-not ('System.Data.SQLite.SQLiteConnection' -as [type])) { Write-Output 'НЕТ: тип System.Data.SQLite не загрузился'; [Environment]::Exit(1) }

    $db = Join-Path $env:TEMP '1c-embedded-sqlite-test.db'
    Remove-Item $db -ErrorAction SilentlyContinue
    $conn = New-Object System.Data.SQLite.SQLiteConnection("Data Source=`"$db`";Version=3;")
    $conn.Open()
    $cmd = $conn.CreateCommand()
    $cmd.CommandText = "CREATE TABLE t (id INTEGER PRIMARY KEY, v TEXT); INSERT INTO t (v) VALUES ('проверка'); SELECT v FROM t;"
    $v = $cmd.ExecuteScalar()
    $cmd.CommandText = 'SELECT sqlite_version();'
    $ver = $cmd.ExecuteScalar()
    $cmd.Dispose()
    $conn.Close()
    Remove-Item $db -ErrorAction SilentlyContinue
    if ($v -ne 'проверка') { Write-Output "НЕТ: чтение после записи вернуло '$v'"; [Environment]::Exit(1) }
    Write-Output "SQLITE EMBEDDED OK: sqlite $ver, запись/чтение подтверждены, драйвер: $libDir"
    # [Environment]::Exit вместо exit: noConsole-exe от ps2exe после exit умирает до ~минуты
    [Environment]::Exit(0)
}

# --- Режим проверки ntfy-уведомлений (без показа окна) -------------------------------
if ($TestNotify) {
    if (-not (Test-Path -LiteralPath $ConfigPath)) {
        Write-Output "НЕТ: конфиг не найден: $ConfigPath"
        [Environment]::Exit(1)
    }
    try { $cfgN = [IO.File]::ReadAllText($ConfigPath, $encUtf8) | ConvertFrom-Json }
    catch { Write-Output "НЕТ: ошибка разбора конфига: $($_.Exception.Message)"; [Environment]::Exit(1) }
    $ntfyN = $cfgN.Ntfy
    if (-not ($ntfyN -and $ntfyN.Url -and $ntfyN.Topic)) {
        Write-Output 'НЕТ: в конфиге нет секции Ntfy (URL/топик) — заполните её в окне настроек (⚙).'
        [Environment]::Exit(1)
    }
    $passN = Get-NtfyPlainPassword ([string]$ntfyN.PasswordEnc)
    if (-not $passN) {
        Write-Output 'НЕТ: пароль не задан или не расшифровывается (другая машина/пользователь?) — введите заново в окне настроек.'
        [Environment]::Exit(1)
    }
    $modeN = [string]$ntfyN.Mode
    if ($modeN -ne 'topic') { $modeN = 'json' }   # отсутствие/мусор = основной способ
    # тест шлётся всегда (явное действие), но при истёкшем периоде наблюдения предупредить
    $watchN = Get-NtfyWatchState $ntfyN
    $watchWarnN = ''
    if ($watchN.Mode -eq 'final' -or $watchN.Mode -eq 'done') {
        $watchWarnN = (' ВНИМАНИЕ: период наблюдения истёк ({0:dd.MM.yyyy}) — автоматические итоги прогона НЕ отправляются (продлить: настройки, «Продлить с сегодня»).' -f $watchN.ActiveUntil)
    }
    try {
        Send-NtfyPush -Url ([string]$ntfyN.Url) -Topic ([string]$ntfyN.Topic) `
            -User ([string]$ntfyN.User) -Password $passN `
            -Title "${AppName}: тест ntfy" -Message 'Тестовое уведомление из командной строки (-TestNotify).' `
            -Priority 'default' -Tags @('electric_plug') -Mode $modeN
        Write-Output "NTFY OK: сервер $($ntfyN.Url), топик $($ntfyN.Topic), способ $modeN — уведомление отправлено, проверьте телефон.$watchWarnN"
        [Environment]::Exit(0)
    }
    catch {
        Write-Output "НЕТ: не удалось отправить: $($_.Exception.Message)"
        [Environment]::Exit(1)
    }
}

# --- Режим проверки: собрать все окна и выйти ---------------------------------------
if ($Validate) {
    $null = Build-SettingsWindow -ConfigFile $ConfigPath   # XAML настроек парсится и строится
    $null = Build-ScheduleWindow                           # XAML расписания парсится и строится
    $null = Build-ScheduleEditWindow -WindowTitle 'Проверка' -Time '03:00' -Days @(1, 7)   # и диалог расписания
    Write-Output 'XAML OK: главное окно, окно настроек, окно расписания и диалог расписания собраны без ошибок'
    [Environment]::Exit(0)
}

# --- Тихий режим (-Silent): фоновый бэкап всех баз без окна (для Планировщика) ------
# Тот же движок, что и в GUI (scriptblock воркера), но синхронно и без показа окна.
if ($Silent) {
    # воркер пишет лог в каталог назначения из конфига; ошибки до чтения конфига —
    # во временный файл, потому что каталог назначения на этом этапе ещё неизвестен
    $silLog = Join-Path ([IO.Path]::GetTempPath()) 'T-REX-Backup1C-silent.log'
    $silFatal = {
        param([string]$Message)
        try {
            Add-Content -LiteralPath $silLog -Value ('{0:yyyy-MM-dd HH:mm:ss} [ERROR] {1}' -f (Get-Date), $Message) -Encoding UTF8
        } catch { }
    }
    $silExit = 1
    if (-not (Test-Path -LiteralPath $ConfigPath)) {
        & $silFatal "Тихий режим: конфиг не найден: $ConfigPath"
    }
    else {
        $cfg = $null
        try { $cfg = [IO.File]::ReadAllText($ConfigPath, $encUtf8) | ConvertFrom-Json }
        catch { & $silFatal "Тихий режим: ошибка разбора конфига: $($_.Exception.Message)" }
        if ($cfg -and ((-not $cfg.Destination) -or (-not $cfg.Bases) -or @($cfg.Bases).Count -eq 0)) {
            & $silFatal 'Тихий режим: в конфиге не заполнены Destination (папка архивов) и/или Bases.'
            $cfg = $null
        }
        if ($cfg) {
            $sync = [hashtable]::Synchronized(@{})
            $sync.Config     = $cfg
            $sync.ConfigPath = $ConfigPath
            $sync.AppDir     = $appDir
            $sync.EmbeddedSqlite = $null
            if ($embeddedSqliteManagedFx -or $embeddedSqliteManagedCore) {
                $sync.EmbeddedSqlite = @{
                    ManagedFx   = $embeddedSqliteManagedFx
                    InteropFx   = $embeddedSqliteInteropFx
                    ManagedCore = $embeddedSqliteManagedCore
                    InteropCore = $embeddedSqliteInteropCore
                }
            }
            $sync.LogQueue = [System.Collections.ArrayList]::Synchronized((New-Object System.Collections.ArrayList))
            $sync.LogPath = $null
            $sync.Phase = 'Подготовка'; $sync.Total = 0; $sync.Progress = 0
            $sync.Ok = 0; $sync.Failed = 0; $sync.CancelRequested = $false
            $sync.Aborted = $false; $sync.FatalError = $false; $sync.ExitCode = $null; $sync.Done = $false

            & $script:backupWorker $sync

            if ($null -ne $sync.ExitCode) { $silExit = [int]$sync.ExitCode }
        }
    }
    [Environment]::Exit($silExit)
}

$uiTimer.Start()
[void]$win.ShowDialog()
